static const struct RFStoryRace sRace_349 = {60, COMPOUND_STRING("La práctica empieza ahora.\nTienes 60 segundos. Habla con\pRoque en Entrada del Cañón\nSevault. Puedes volver para\preintentarlo."), COMPOUND_STRING("Llegaste fuera de tiempo. El\nencargo sigue en el diario.\pVuelve con Tina, en Isla Siete,\npara empezar otra vez."), COMPOUND_STRING("Vuelve al puesto de salida. La\npráctica dura 60 segundos. Si\pguardaste y saliste del juego,\npuedes empezar de nuevo.")};
