static const struct RFStoryScene sScenes[] = {
    {0, 1, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Una placa llegó sin procedencia.\nIria copia marcas en Ruta 4;\ppregúntale si reconoce su\ndibujo. No retires nada de la\pmontaña."), COMPOUND_STRING("Iria reconoce el trazo de una\nantigua cantera. La\pinvestigación empieza con una\nprocedencia, no con una leyenda."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {1, 2, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("La placa salió de una\nescombrera. Edda compara rocas\pen Monte Moon. Una Piedra Lunar\nayudará a separar las marcas\pnaturales de las talladas."), COMPOUND_STRING("Edda distingue tres técnicas.\nUna sola pieza no demuestra que\ptoda Kanto perteneciera a un\nmismo pueblo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {2, 2, RF_STORY_CLUES, 0, 0x00000007, COMPOUND_STRING("Compara los atriles de Monte\nMoon B2, Túnel Roca B1 y el\plaboratorio de Canela. Anota los\ntres antes de presentar una\pconclusión."), COMPOUND_STRING("Los tres calcos quedan\narchivados juntos. Las marcas\pviajaron con sus artesanos; no\neran un mapa de conquista."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {2, 0, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El laboratorio puede recuperar\nun Aerodactyl del Ámbar Viejo.\pMuéstralo a Alma: estudiar un\nser vivo exige cuidado, no solo\pentusiasmo."), COMPOUND_STRING("Alma separa hechos y conjeturas\nen la exposición. Tu Aerodactyl\ppermanece contigo; el museo\nconserva únicamente sus\pobservaciones."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {0, 3, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Las copias se compartirán con el\narchivo de Celio. Cuando seas\pCampeón, busca a Nilo en el\nCentro Pokémon de Isla Uno."), COMPOUND_STRING("Nilo recibe el informe y permite\ncontrastarlo con los archivos de\pSete. No necesita extraer una\nsola piedra de las ruinas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {3, 4, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Tala estudia cómo cambian los\nsignos entre islas. Lleva un\pUnown para comparar sus formas;\nno lo entregarás ni lo dejarás\pen las ruinas."), COMPOUND_STRING("Tala encuentra diferencias entre\nlos signos. Los Unown ayudan a\pleerlos, pero no convierten una\ninterpretación en verdad\pabsoluta."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {4, 5, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("El atril ordena tres etapas:\nprimero roca, después agua y al\pfinal vida. Lee sus preguntas en\nla Cámara Monan. Puedes volver a\pintentarlo."), COMPOUND_STRING("La secuencia abre el índice de\nla cámara, no una puerta\psellada. El índice describe\nintercambios entre comunidades,\psin un reino perdido."), sPuzzle_6, 3, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {4, 0, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lleva las conclusiones a Alma.\nLa exposición debe explicar qué\psabemos, qué ignoramos y por qué\nlas piezas siguen en sus\plugares."), COMPOUND_STRING("La sala dedica su nueva cartela\na las comunidades de Kanto y\pSete. El expediente queda\nabierto a futuras preguntas,\ppero esta investigación\nconcluye."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {6, 7, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Una remesa usa la dirección de\nBill sin permiso. Leila teme que\palguien esté suplantando a sus\nclientes. Conserva los datos y\pconsulta a Tomás."), COMPOUND_STRING("La dirección fue copiada de un\narchivo viejo. Tomás advierte a\pBill y separa esa copia de la\nred actual."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {7, 8, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Cuando Silph vuelva a trabajar\ncon normalidad, Ivo podrá\previsar el envío. No entres en\nzonas cerradas para adelantar la\pinvestigación."), COMPOUND_STRING("Ivo conserva el registro y\nconfirma que un intermediario de\pAzulona usó el archivo. Las\ncomunicaciones personales quedan\pfuera del análisis."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {8, 9, RF_STORY_BATTLE, TRAINER_RF_STORY_0, 0x00000000, COMPOUND_STRING("Lio aceptó transportar paquetes\nsin conocer su contenido. Quiere\pcomprobar si puedes acompañarlo\nsin depender de quienes le\ppagaban. Su combate es\nvoluntario."), COMPOUND_STRING("Lio rompe su contrato y entrega\nlas etiquetas. No revela\pdirecciones privadas: solo la\nruta de los paquetes."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {9, 7, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Las etiquetas parecen señalar a\nun Pokémon digital. Lleva una\pcopia a Tomás; perseguir a un\nPorygon no es una forma de pedir\payuda."), COMPOUND_STRING("Bill y Tomás sustituyen las\nclaves expuestas. El problema\pera el permiso de acceso, no la\nexistencia de Porygon."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {7, 10, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Vera necesita comprobar una\ninstalación sin capturar a los\pPokémon que viven allí. Acércale\nun compañero eléctrico dispuesto\pa colaborar."), COMPOUND_STRING("Vera prueba una alimentación\naislada. La Central conserva su\phábitat y deja de ser una excusa\npara encerrar Pokémon."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {10, 8, RF_STORY_CLUES, 0, 0x00000038, COMPOUND_STRING("Antes de conectar nada, revisa\nlos nodos de Silph 1F, la casa\pde Bill y el laboratorio de\nCanela. Las tres comprobaciones\pforman un único informe."), COMPOUND_STRING("Ivo recibe las tres\nverificaciones. La nueva copia\ptiene procedencia y permisos\nclaros; una avería no borrará el\ptrabajo de los demás."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {8, 7, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Registra a Porygon en tu Pokédex\ny consulta a Tomás. El estudio\putiliza tus observaciones; tu\nPokémon no se transfiere a\pningún ordenador."), COMPOUND_STRING("Tomás documenta cómo colaborar\ncon Porygon sin confundirlo con\puna herramienta desechable."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {7, 11, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Ya como Campeón, revisa la\nterminal del antiguo almacén\pRocket de Isla Cinco. Debes\nllegar por los accesos normales\pde tu aventura."), COMPOUND_STRING("La terminal queda aislada y el\narchivo limpio vuelve a Silph.\pBill conserva una copia de\nemergencia. La red ya no depende\pde una clave robada."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {12, 13, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Cuando el señor Fuji esté a\nsalvo, visita a Inés en su casa\pde Pueblo Lavanda. Un Cubone del\nrefugio evita los ruidos del\pexterior."), COMPOUND_STRING("Inés te presenta al pequeño sin\nforzarlo a acercarse. Ayudar\pcomienza por respetar la\ndistancia que pide."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {13, 12, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Un compañero de su especie puede\nhacer la visita más tranquila.\pLleva Cubone o Marowak a Rosa,\nsin entregarle tu Pokémon."), COMPOUND_STRING("Rosa observa un primer\nacercamiento. Tu compañero\pvuelve contigo; el pequeño del\nrefugio empieza a reconocer\pvoces amigas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {12, 14, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Darío conoce un tramo tranquilo\nde Ruta 12. Pídele que revise el\pcamino antes de organizar un\npaseo con el refugio."), COMPOUND_STRING("Darío retira su equipo de pesca\ndel paso. Inés podrá acompañar\pal grupo sin obligarlo a\natravesar una multitud."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {14, 15, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Zaira preparará objetos para que\nel pequeño elija cómo jugar.\pLleva una Pokémuñeca a la\noficina del Safari; se consume\psolo al confirmar."), COMPOUND_STRING("Zaira incorpora la muñeca al\nmaterial del refugio. Nadie\pexige que Cubone juegue con ella\nni que deje su hueso."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {15, 13, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("La salida requiere un botiquín\npara todo el grupo. Inés\pnecesita un Antídoto; comprarlo\no encontrarlo sirve, y la\pentrega queda registrada."), COMPOUND_STRING("El botiquín queda preparado. El\ncuidado cotidiano permite que el\prefugio organice más paseos sin\nasumir riesgos innecesarios."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {13, 12, RF_STORY_CLUES, 0, 0x000001C0, COMPOUND_STRING("Lee los memoriales de las\nplantas 5, 6 y 7 de la Torre\pPokémon. Rosa reunirá las tres\nnotas en un solo recuerdo, sin\pllevarse sus ofrendas."), COMPOUND_STRING("Rosa prepara un recuerdo con\npermiso del refugio. La historia\pno borra la pérdida; deja\nespacio para hablar de ella."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {12, 14, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El grupo ha realizado su primer\npaseo acompañado. Pregunta a\pDarío cómo fue y lleva noticias\na quienes esperan, sin buscar al\ppequeño por tu cuenta."), COMPOUND_STRING("Darío cuenta que Cubone quiso\nregresar antes que los demás. El\pgrupo lo respetó; elegir volver\ntambién es ganar confianza."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {14, 13, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El refugio tiene una nueva\nrutina. Visita a Inés para\pcerrar el informe y saber qué ha\nelegido hacer Cubone."), COMPOUND_STRING("Cubone decide quedarse con Inés\ny salir con el grupo cuando le\papetezca. Puedes visitarlo aquí.\nTu Pokémon nunca fue entregado\pal refugio."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {16, 17, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("La Pokédex de Oak necesita\nobservaciones de campo. Registra\pCaterpie y visita a Silva en\nBosque Verde para aprender cómo\panotar su hábitat."), COMPOUND_STRING("Silva registra luz, refugio y\nalimento. La ficha de Caterpie\pya no es solo un número."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {17, 18, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Compara la vida del bosque con\nla de una cueva. El geólogo\pBruno te espera en Túnel Roca B1\ncuando tengas el registro de\pGeodude."), COMPOUND_STRING("Bruno distingue huellas\nrecientes de marcas antiguas. El\pgrupo evita usar un nido como\nzona de descanso."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {18, 19, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Mar estudia los lugares donde\ndescansan los Pokémon de la\pcosta. Registra Seel antes de\nconsultar sus notas en Islas\pEspuma."), COMPOUND_STRING("Mar añade zonas de descanso al\ninforme. Los investigadores\pcambian su recorrido para no\nocuparlas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {19, 20, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El Safari necesita comparar sus\ncuidados con los hábitats\psilvestres. Registra Nidoran\nhembra y habla con Salo en la\poficina de Fucsia."), COMPOUND_STRING("Salo corrige el plano de\nrefugios. La conclusión\pdistingue lo observado de lo que\naún debe comprobarse."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {20, 10, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El comportamiento eléctrico\ntambién depende del entorno.\pRegistra Voltorb y contrasta sus\nlugares de descanso con Vera en\pla Central."), COMPOUND_STRING("Vera anota distancias seguras\npara sus pruebas. La\pinvestigación de Oak y la\nreparación de la red comparten\pobservaciones, no Pokémon."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {10, 21, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Nora compara los refugios\ncálidos de Isla Uno. Registra\pPonyta y lleva la ficha a Camino\nCandente cuando puedas viajar a\pSete."), COMPOUND_STRING("Nora encuentra que descanso y\ntemperatura deben anotarse\pjuntos. Un dato aislado no\nexplica todo el comportamiento."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {21, 16, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Ada reunirá las notas de bosque,\ncueva, costa, Safari, Central e\pislas. Vuelve al laboratorio de\nPaleta para revisar sus\pdiferencias."), COMPOUND_STRING("Ada conserva las discrepancias\nen vez de borrarlas. El archivo\pde Oak explica cómo se obtuvo\ncada dato."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {16, 16, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Revisa las conclusiones con Ada.\nLos demás registros de Pokédex\pseguirán ampliando el archivo;\nno tienes que completarlos todos\ppara cerrar esta campaña."), COMPOUND_STRING("Oak recibe el estudio y Ada\nfirma también tu trabajo. La\pinvestigación concluye con una\nmetodología que otros podrán\prepetir."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {22, 23, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Un excursionista pidió ayuda\nantes de entrar en Monte Moon.\pPaz organiza el puesto de Ruta 3\ny necesita una Poción para su\pbotiquín."), COMPOUND_STRING("Paz prepara el puesto sin enviar\na nadie solo a la cueva. Avisar\pa tiempo ha evitado una búsqueda\nnocturna."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {23, 1, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Paz ha recibido dos indicaciones\ndistintas sobre una salida. Iria\pestá comprobando las señales de\nRuta 4; habla con ella antes de\pmover al grupo."), COMPOUND_STRING("Iria corrige una copia del\nplano. La patrulla acuerda un\ppunto de regreso que todos\npueden reconocer."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {1, 24, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Teo mantiene a salvo a un\nexcursionista desorientado en\pTúnel Roca. No hace falta\nenfrentarse a él: necesita\pnoticias claras de la salida."), COMPOUND_STRING("Teo puede acompañar al\nexcursionista hasta un punto\pseguro. El rescate queda anotado\ny la familia recibe el aviso."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {24, 24, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("El siguiente turno necesita un\nRepelente para reducir\pencuentros durante el traslado.\nEntrégalo al puesto; no se usa\psobre tu equipo."), COMPOUND_STRING("El relevo recibe el material y\nconfirma la salida. Teo conserva\psu puesto para orientar a otros\nviajeros."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {24, 25, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Rubén reúne los avisos para las\nfamilias de los excursionistas.\pLleva la confirmación a Ciudad\nFucsia, sin dar por desaparecido\pa nadie más."), COMPOUND_STRING("Rubén cierra la búsqueda y\nconserva los teléfonos de\pcontacto. La familia ya sabe que\nel grupo está de regreso."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {25, 26, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Yara pide comparar señales en\nBosque Baya, en Isla Tres. La\ppatrulla trabaja después del\nrescate de Pedrita y no\psustituye aquella historia."), COMPOUND_STRING("Yara confirma una ruta de\nretorno y mantiene una patrulla\pvisible. Los nuevos visitantes\ntendrán un punto al que pedir\payuda."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {26, 15, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("La patrulla necesita pautas para\nayudar a Pokémon asustados sin\pacorralarlos. Zaira revisará las\nnotas en la oficina del Safari."), COMPOUND_STRING("Zaira incorpora una distancia de\nseguridad a las instrucciones.\pLa red aprende de cada rescate,\nen vez de limitarse a contarlos."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {15, 22, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lina espera los informes de las\npatrullas. Vuelve a Ciudad Verde\ppara dejar acordados los puestos\nde auxilio y los avisos a las\pfamilias."), COMPOUND_STRING("Los puestos quedan coordinados.\nLina abre encargos de\pprovisiones repetibles,\nseparados de esta campaña y con\pun límite diario."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {6, 27, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Leila trae una invitación de\nintercambio para una entrenadora\pde Johto. Hana espera en Ciudad\nCarmín y decidirá si quiere\pparticipar."), COMPOUND_STRING("Hana acepta intercambiar\napuntes. Nadie apuesta Pokémon\pni condiciona tu paso por la\nciudad."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {27, 27, RF_STORY_BATTLE, TRAINER_RF_STORY_1, 0x00000000, COMPOUND_STRING("Hana quiere estudiar cómo\nrespondes a un equipo de apoyo.\pPuedes rechazar el combate y\nretomarlo cuando tu equipo esté\ppreparado."), COMPOUND_STRING("Hana anota tus decisiones y te\nentrega una copia de su\pestrategia. El intercambio\ncontinúa con Ken, en Azulona."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {27, 28, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Ken trae observaciones de Hoenn.\nCompara con él cómo cambia un\pequipo cuando no puede depender\nde un único movimiento."), COMPOUND_STRING("Ken comparte sus notas y propone\nuna práctica. Su objetivo es\pmostrar alternativas, no\nmodificar las reglas de tu\ppartida."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {28, 28, RF_STORY_BATTLE, TRAINER_RF_STORY_2, 0x00000000, COMPOUND_STRING("Ken ha preparado un equipo con\nrespuestas distintas a un mismo\prival. El combate es opcional y\npodrás volver si pierdes."), COMPOUND_STRING("Ken encuentra una debilidad en\nsus propios apuntes. Ambos\pconservan sus equipos y sus\nreglas habituales."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {28, 29, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Mael quiere contrastar sus\nanotaciones de Sinnoh con las\ptuyas. Te espera en Azafrán\ndespués de obtener seis\pmedallas."), COMPOUND_STRING("Mael reserva espacio para los\nerrores de su hipótesis. Propone\pcomprobarla contigo en un\ncombate de práctica."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {29, 29, RF_STORY_BATTLE, TRAINER_RF_STORY_3, 0x00000000, COMPOUND_STRING("Una hipótesis también debe\nsobrevivir a una derrota. Mael\pha preparado un equipo\nequilibrado; vuelve cuando\pquieras intentar su práctica."), COMPOUND_STRING("Mael corrige su propuesta sin\natribuir el resultado a una\pregión. Sus notas pasan a formar\nparte del intercambio."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {29, 30, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Sara reúne el intercambio final\nen Isla Siete. Cuando seas\pCampeón, llévale los cuadernos\nde Hana, Ken y Mael."), COMPOUND_STRING("Sara descubre que los cuadernos\ncoinciden en escuchar al\pcompañero. Propone un último\ncombate sin apuestas ni cambios\ppermanentes."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {30, 30, RF_STORY_BATTLE, TRAINER_RF_STORY_4, 0x00000000, COMPOUND_STRING("Sara quiere cerrar el\nintercambio en combate. Puedes\pintentarlo varias veces; cada\nderrota conserva el progreso de\plos demás encuentros."), COMPOUND_STRING("Los cuatro visitantes firman el\ncuaderno compartido. No hay una\pescuela vencedora: quedan\nestrategias que otros\pentrenadores podrán discutir."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {31, 33, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Mara ha encontrado una lista de\nobjetos sin propietarios. La\pprimera anotación apunta a una\nplaca de Cabo Extremo, en Isla\pDos."), COMPOUND_STRING("La placa vincula el inventario\ncon antiguas rutas de ayuda. No\pseñala un cofre: enumera lo que\ndebía devolverse."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {33, 32, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("La lista menciona un pilar\nlevantado en memoria de quienes\pfaltan. Lee su baliza en Isla\nCinco sin tocar las ofrendas."), COMPOUND_STRING("La baliza conserva los nombres\nde una tripulación. Mara podrá\pbuscar a sus familias, en lugar\nde vender lo hallado."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {32, 31, RF_STORY_CLUES, 0, 0x0001C000, COMPOUND_STRING("Busca los tres testimonios\nseñalados en Carmín, Ruta 12 y\pCabo Extremo. Juntos permitirán\nreconstruir el inventario, sin\pconvertir cada nota en un\nencargo."), COMPOUND_STRING("Las tres notas confirman la ruta\ny sus destinatarios. Mara guarda\puna copia pública y protege las\ndirecciones privadas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {31, 3, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Una Perla común permitirá\nreconstruir una pieza del\pinventario sin usar objetos\núnicos. Nilo preparará una\préplica documentada para las\nfamilias."), COMPOUND_STRING("Nilo identifica la réplica como\ntal. Las familias reciben su\phistoria sin que nadie les venda\nuna antigüedad falsa."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {3, 4, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El último nombre aparece también\nen Valle Ruinas. Tala comprobará\pla lectura sin relacionar\ncualquier ruina con un mismo\pautor."), COMPOUND_STRING("Tala distingue dos personas con\nnombres parecidos. Evita que el\parchivo atribuya la historia a\nla familia equivocada."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {4, 34, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El diario de Leyendas tiene el\nencargo Espíritus de Alola.\pReúne el registro de sus cuatro\nguardianes y vuelve a Gael. Si\pya lo completaste, tu archivo\nsirve: nadie debe volver a\pcapturarlos."), COMPOUND_STRING("El archivo de los guardianes\nexplica la ruta del sur. Gael\psepara su cuidado del valor del\ninventario; no aparece ningún\pejemplar duplicado."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {34, 31, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El inventario está documentado.\nDevuélvelo a Mara en Carmín para\pque pueda organizar las entregas\na las familias."), COMPOUND_STRING("Mara prepara las devoluciones.\nEl valor de lo encontrado está\pen que vuelva a tener dueño."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {31, 0, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Alma expondrá una copia del\ninventario y explicará qué se\pdevolvió. Visítala en el museo\npara cerrar la búsqueda."), COMPOUND_STRING("La cartela reconoce a las\nfamilias y a quienes mantuvieron\plas rutas de ayuda. El tesoro\nqueda compartido como historia,\pno repartido como botín."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {22, 36, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Riel organiza prácticas de\norientación entre Ruta 22 y\pCiudad Verde. Habla con él: no\nnecesitarás abandonar a ningún\pcompañero."), COMPOUND_STRING("Riel explica el trayecto y sus\npuestos. Si una práctica se\pinterrumpe, se vuelve a empezar\nsin perder el encargo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {36, 22, RF_STORY_RACE, 0, 0x00000000, COMPOUND_STRING("Inicia la práctica hablando otra\nvez con Riel en Ruta 22. Lleva\psu mensaje a Lina en Ciudad\nVerde antes de 45 segundos.\pPuedes reintentarlo."), COMPOUND_STRING("Lina recibe el mensaje a tiempo.\nUna llegada segura vale más que\pel récord; Riel conserva el\npuesto para nuevas prácticas."), NULL, 0, &sRace_57, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {22, 17, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("Silva propone recordar el orden\nroca, agua y vida con un juego\pde preguntas. Un error reinicia\nel juego, no tu aventura."), COMPOUND_STRING("Silva entrega la secuencia\ncorrecta al grupo. El juego\penseña a confirmar señales antes\nde seguir una ruta."), sPuzzle_58, 4, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {17, 34, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Ya como Campeón, Gael prepara\nuna expedición de cinco puestos\pen Cañón Sétano. Entrega dos\nSuperrepelentes para la reserva\pcomún."), COMPOUND_STRING("Gael guarda las provisiones de\nla expedición. No se retira tu\pequipo ni se modifica lo que\nllevas equipado."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {34, 34, RF_STORY_CLUES, 0, 0x00003E00, COMPOUND_STRING("Pasa por los cinco puestos\nseñalados de Cañón Sétano y\pregresa a Gael. El cuaderno\nconserva cada puesto visitado\paunque guardes y salgas."), COMPOUND_STRING("Gael comprueba los cinco sellos.\nTodos los puestos conservan una\pindicación de regreso; la\nexpedición no termina en el\plugar más lejano."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {34, 35, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Belén comparará la expedición\ncon su patrulla de Isla Seis.\pLlévale el informe para que\notros puedan escoger una ruta\padecuada."), COMPOUND_STRING("Belén incorpora caminos de\nretorno más cortos para quienes\plos necesiten. La ruta deja de\ndepender de un único guía."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {35, 34, RF_STORY_BATTLE, TRAINER_RF_STORY_5, 0x00000000, COMPOUND_STRING("Gael simula el último encuentro\nde una expedición. Es un combate\pvoluntario con tu equipo\nhabitual; puedes volver a\pprepararte si pierdes."), COMPOUND_STRING("Gael da por finalizada la\npráctica. La prueba no exigía\pagotar recursos, sino reconocer\ncuándo prepararse mejor."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {34, 22, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Entrega a Lina el cuaderno de\norientación y expediciones. Cada\pparticipante ha confirmado su\nregreso; falta cerrar el\pregistro común."), COMPOUND_STRING("Lina archiva la ruta, los cinco\nsellos y el regreso del grupo.\pLa campaña termina con todas las\npersonas localizadas y encargos\pdiarios opcionales."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {16, 55, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Oak quiere saber qué Pokémon\nviven hoy en cada ruta, no solo\pcuáles vivían cuando escribió\nsus libros. Cora empezará el\pcenso en Ruta 2; preséntate\nallí."), COMPOUND_STRING("Cora te entrega una libreta con\ncolumnas vacías. Cada cifra\pdeberá salir de algo que hayas\nvisto o registrado tú."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {55, 55, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("El Bosque Verde cambia con cada\nestación. Registra tres capturas\pallí; después puedes quedarte\ncon ellos o liberarlos en el\pmismo bosque."), COMPOUND_STRING("Cora anota especie, hora y claro\nde cada captura. Tres registros\pno son un censo, pero ya\nmuestran que el bosque no es\pigual de día que de noche."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {55, 56, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Algunos Pokémon se esconden si\nlos persigues. Olmo cuida el\pBosque Verde y quiere saber si\naún vive allí Pikachu. Basta con\pverlo; no hace falta atraparlo."), COMPOUND_STRING("Olmo marca el claro donde lo\nviste. Saber que sigue allí vale\pmás que llevárselo: el bosque\nnecesita a quienes lo habitan."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {56, 56, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Olmo estudia cómo reaccionan los\nPokémon cuando alguien entrena\pcon respeto. Gana ocho combates\ncontra salvajes en cualquier\pruta; no tienes que capturar a\nninguno."), COMPOUND_STRING("Olmo compara tus notas con las\nsuyas. Los Pokémon de las rutas\pno son enemigos: son vecinos que\ntambién ponen a prueba a quien\ppasa."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {56, 57, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("El censo no puede quedarse en la\nhierba. Vito estudia ríos y\pestanques al norte de Ciudad\nCeleste. Registra cuatro\pcapturas de tipo Agua y llévale\nlas notas."), COMPOUND_STRING("Vito agrupa tus registros por\ncorriente y profundidad. El agua\pde Kanto une rutas que en el\nmapa parecen lejanas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {57, 57, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Vito quiere saber cuándo cambia\nun Pokémon que crece junto a una\ppersona. Acompaña a dos Pokémon\nhasta su evolución; no hay prisa\pni un método mejor que otro."), COMPOUND_STRING("Vito anota cuánto tiempo pasó\ncada uno contigo. Evolucionar no\pes una meta impuesta: es una\netapa que el censo también\precuerda."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {57, 58, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Ya como Campeón, visita la\nguardería de Isla Cuatro. Nerea\pregistra los primeros días de\nlos Pokémon recién nacidos. Haz\peclosionar un huevo y cuéntale\ncómo fue."), COMPOUND_STRING("Nerea añade una página nueva al\ncenso: la de quienes aún no\pconocen ninguna ruta. Tu\ncompañero sigue contigo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {58, 16, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Nerea completa la última\ncolumna. Lleva la libreta a Ada:\pOak la comparará con sus\nregistros antiguos."), COMPOUND_STRING("Ada y Oak descubren especies que\nse mudaron y otras que\pregresaron. El censo llevará tu\nnombre junto al de Cora, Olmo,\pVito y Nerea. Cora visitará el\nlaboratorio para mantenerlo al\pdía."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {60, 61, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Tano entrenó durante años y\nahora enseña en Plateada. Su\palumna Pía practica en Ruta 3,\npero se rinde tras cada derrota.\pVe a conocerla."), COMPOUND_STRING("Pía admite que teme decepcionar\na Tano. Le cuentas que tu\pprimera derrota también te\nenseñó algo, y decide seguir\pintentándolo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {61, 61, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Pía quiere ver cómo afrontas un\ncombate tras otro. Gana cinco\pcombates contra entrenadores en\ncualquier lugar; ella anotará\pqué decisiones tomaste."), COMPOUND_STRING("Pía repasa sus notas. No ganaste\npor tener los Pokémon más\pfuertes, sino por cambiar de\nplan a tiempo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {61, 62, RF_STORY_BATTLE, TRAINER_RF_STORY_6, 0x00000000, COMPOUND_STRING("Quim, el otro alumno de Tano,\nestudia cada combate en su\pcuaderno. Te espera en Ciudad\nCeleste para una práctica\pvoluntaria."), COMPOUND_STRING("Quim cierra el cuaderno con una\nsonrisa. Ha descubierto que un\pplan escrito también tiene que\nescuchar a sus Pokémon."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {62, 60, RF_STORY_CHOICE, 0, 0x00000000, COMPOUND_STRING("Pía y Quim quieren saber cómo\nseguirá su entrenamiento. Tano\pte pedirá tu opinión en\nPlateada."), COMPOUND_STRING("Tano asiente. Les dará tiempo\npara equivocarse y entender por\pqué. Pía respira aliviada."), NULL, 0, NULL, RF_STORY_CHOICE_ESCUELA_EXIGENCIA, COMPOUND_STRING("Tano te pregunta: ¿debería\nexigirles más a sus alumnos?"), NULL, COMPOUND_STRING("Tano acepta. Les pedirá más cada\ndía, sin quitarles el derecho a\pdescansar. Quim ya prepara un\nhorario nuevo.")},
    {60, 60, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Tano quiere hablar contigo\ncuando reúnas cuatro medallas.\pDice que entonces sabrás algo\nque a él le costó años aprender."), COMPOUND_STRING("Tano te cuenta que ganó muchas\nmedallas, pero recuerda mejor a\pquienes le ayudaron a\nlevantarse. Quiere que sus\palumnos lo sepan antes que él."), NULL, 0, NULL, RF_STORY_CHOICE_ESCUELA_EXIGENCIA, NULL, COMPOUND_STRING("Tano endureció las prácticas\ncomo sugeriste. Quiere hablar\pcontigo cuando reúnas cuatro\nmedallas para saber si exigir ha\pservido de algo."), NULL},
    {60, 61, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Tano quiere saber cómo está Pía\ndespués de estas semanas.\pVisítala en Ruta 3."), COMPOUND_STRING("Pía ya no se rinde tras una\nderrota: anota qué falló y\pvuelve a intentarlo con calma."), NULL, 0, NULL, RF_STORY_CHOICE_ESCUELA_EXIGENCIA, NULL, NULL, COMPOUND_STRING("Pía entrena cada mañana con el\nhorario de Tano. Está cansada,\ppero ha aprendido a pedir un\ndescanso cuando lo necesita.")},
    {61, 62, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Quim calcula que un entrenador\nde verdad ha disputado al menos\pcincuenta combates. Cuando\nalcances esa cifra, búscalo en\pCiudad Celeste."), COMPOUND_STRING("Quim repasa tus combates y deja\nde contar victorias. Ahora le\pinteresa cuántas veces cambiaste\nde estrategia."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {62, 60, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Pía y Quim quieren presentar a\nTano lo que han aprendido.\pAcompáñalos a Plateada para\ncerrar esta etapa."), COMPOUND_STRING("Tano abre su escuela a quien\nquiera aprender a perder sin\prendirse. Pía y Quim enseñarán a\nlos siguientes alumnos."), NULL, 0, NULL, RF_STORY_CHOICE_ESCUELA_EXIGENCIA, NULL, NULL, COMPOUND_STRING("Tano reconoce que exigir\nfuncionó porque Pía y Quim\ppudieron decir cuándo parar. La\nescuela tendrá horarios\pestrictos y descansos\nobligatorios.")},
    {63, 63, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Brisa coordina los rescates del\nTúnel Roca. Antes de entrar,\pcada voluntario deja dos Cuerdas\nHuida en la reserva común. Nadie\pdebería quedarse sin salida."), COMPOUND_STRING("Brisa guarda las cuerdas junto a\nla entrada. Si alguien se\ppierde, la reserva ya está\npreparada."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {63, 63, RF_STORY_CLUES, 0, 0x000E0000, COMPOUND_STRING("Un excursionista no regresó\nanoche. Brisa marcó tres puntos\ppor los que pudo pasar: dos en\nel Túnel Roca y uno en Ruta 10.\pRevísalos y vuelve."), COMPOUND_STRING("Las tres señales coinciden: el\nexcursionista bajó al sótano del\ptúnel. Brisa traza una ruta\nsegura para llegar hasta él."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {63, 64, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Con las señales, Brisa cree\nsaber dónde está Nico. Baja al\psótano del Túnel Roca y\ncomprueba que está bien. No\pintentes sacarlo sin hablar\nantes con él."), COMPOUND_STRING("Nico está cansado pero a salvo.\nSe torció un tobillo y prefirió\pesperar en lugar de arriesgarse\na caer otra vez."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {64, 64, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("El equipo de Nico está agotado\ndespués de protegerlo toda la\pnoche. Dos Superpociones les\npermitirán acompañarlo hasta la\psalida."), COMPOUND_STRING("Los Pokémon de Nico recuperan\nfuerzas. Ahora él puede caminar\pdespacio con ellos a su lado."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {64, 65, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Nico pide que avises a su madre,\nOlga, en Pueblo Lavanda. Él\psaldrá con Brisa en cuanto pueda\napoyar el tobillo."), COMPOUND_STRING("Olga respira por primera vez en\ntoda la noche. Te pide que no le\pcuentes a Nico cuánto se\npreocupó."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {65, 65, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("El Machop de Nico huyó al oír un\nderrumbe. Olga cree que sigue en\pel túnel. Basta con verlo para\nsaber que está bien; no intentes\patraparlo."), COMPOUND_STRING("Olga se tranquiliza. Nico podrá\nbuscar a su compañero cuando se\precupere, con calma y sin\nasustarlo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {65, 64, RF_STORY_BATTLE, TRAINER_RF_STORY_7, 0x00000000, COMPOUND_STRING("Nico quiere volver a entrenar,\npero le tiembla la voz. Propone\pun combate de práctica en el\nsótano del túnel, donde ocurrió\ptodo."), COMPOUND_STRING("Nico sonríe al terminar. El\ntúnel vuelve a ser un lugar que\ppuede recorrer, no solo un mal\nrecuerdo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {64, 63, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Nico sale del túnel con Brisa.\nLleva al Centro el informe del\prescate: lo que funcionó y lo\nque hay que mejorar."), COMPOUND_STRING("Brisa añade una señal fija en\ncada cruce del túnel. Nico\pvolverá a Pueblo Lavanda para\ndescansar con su madre."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {67, 68, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lis cuida el Bosque Baya con su\nfamilia. Cada vez llegan más\pvisitantes y quiere saber qué\npiensa Abel, que pasa allí casi\ptodo el día."), COMPOUND_STRING("Abel cuenta que los Pokémon del\nbosque se esconden cuando hay\pmucho ruido. Antes de decidir\nnada, quiere saber quién vive\pallí."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {68, 68, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Abel quiere saber qué especies\nfrecuentan el bosque. Registra\ptres capturas allí; puedes\nliberarlos después en el mismo\pclaro."), COMPOUND_STRING("Abel anota cada especie junto al\narbusto donde apareció. El\pbosque está más habitado de lo\nque parecía."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {68, 68, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("En invierno, el refugio del\nbosque reparte bayas a los\pPokémon jóvenes. Abel te pide\ncinco Bayas Aranja para la\preserva."), COMPOUND_STRING("Abel guarda las bayas en el\nrefugio. Nadie tendrá que\parrancar frutos verdes cuando\nllegue el frío."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {68, 69, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("Mora, la abuela de Lis, enseña a\nlos visitantes cuándo se recoge\pcada baya. Te espera en el\nPuente Unión con un pequeño\pjuego de preguntas."), COMPOUND_STRING("Mora asiente satisfecha. Quien\nsabe esperar a la cosecha no\pdaña el arbusto que la produce."), sPuzzle_91, 3, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {69, 69, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Mora sostiene que un bosque sano\nse nota en sus Pokémon de tipo\pPlanta. Registra cuatro capturas\nde ese tipo, donde quieras, y\pcuéntale qué viste."), COMPOUND_STRING("Mora compara tus notas con las\nde su juventud. Algunas especies\pvolvieron; otras todavía faltan."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {69, 67, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Con las notas de Abel y las\nsuyas, Mora ha dibujado un mapa\pdel bosque. Llévaselo a Lis: la\nfamilia debe decidir junta."), COMPOUND_STRING("Lis extiende el mapa sobre la\nmesa. Los claros con más Pokémon\pquedan marcados en rojo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {67, 67, RF_STORY_CHOICE, 0, 0x00000000, COMPOUND_STRING("Lis duda entre abrir senderos\npor todo el bosque o cerrar los\pclaros más sensibles. Quiere\nescuchar a alguien de fuera\pantes de decidir."), COMPOUND_STRING("Lis decide cerrar los claros\nmarcados en rojo. Los visitantes\precorrerán solo los senderos del\nborde."), NULL, 0, NULL, RF_STORY_CHOICE_BAYAS_ABIERTAS, COMPOUND_STRING("Lis pregunta: ¿abrimos senderos\nguiados por todo el bosque?"), NULL, COMPOUND_STRING("Lis decide abrir senderos\nguiados por todo el bosque, con\pturnos y guías de la familia.\nLos claros sensibles se\pvisitarán en silencio.")},
    {67, 68, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Abel espera en el Bosque Baya\npara saber qué decidió la\pfamilia. Ve a contárselo; él\npreparará las señales."), COMPOUND_STRING("Abel coloca señales en el borde\ndel bosque. Los claros quedan\ppara los Pokémon y para quien\nsepa observar desde lejos."), NULL, 0, NULL, RF_STORY_CHOICE_BAYAS_ABIERTAS, NULL, NULL, COMPOUND_STRING("Abel prepara turnos de visita\nguiada. El bosque recibe\pvisitantes, pero nunca más de\nlos que sus Pokémon pueden\ptolerar.")},
    {70, 71, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Tobi tiene una saca llena y una\npierna cansada. Te pide llevar\puna carta a Meli, en Ciudad\nVerde. No tiene prisa: solo\pquiere que llegue."), COMPOUND_STRING("Meli abre la carta allí mismo.\nEs de su hermano, que cuenta que\pha visto su primer Pidgeotto."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {71, 70, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Meli escribe una respuesta corta\ny te pide que se la des a Tobi\ppara la próxima ruta del correo."), COMPOUND_STRING("Tobi guarda la carta en el\nbolsillo de las urgentes. Dice\pque las respuestas pesan menos\nque las preguntas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {70, 72, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Teodoro espera un paquete pero\nnunca está en casa: camina por\pla Ruta 1 a todas horas.\nEncuéntralo y pregúntale dónde\pquiere recibirlo."), COMPOUND_STRING("Teodoro se ríe. Quiere recibir\nel paquete en la ruta, junto al\pcartel, porque allí pasa más\ntiempo que en su casa."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {72, 72, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Teodoro cuenta que los salvajes\nasustan a los repartidores\pnuevos. Gana tres combates en la\nhierba para que Tobi vea que el\pcamino es seguro."), COMPOUND_STRING("Teodoro asiente. Los Pokémon de\nla Ruta 1 solo defendían su\psitio; ahora el repartidor sabrá\npor dónde pasar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {72, 70, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Teodoro sugiere que Tobi lleve\nun botiquín en la saca.\pEntrégale dos Pociones de tu\nparte."), COMPOUND_STRING("Tobi guarda las Pociones junto a\nlas cartas. Ahora sabe que\prepartir también es cuidar a\nquien acompaña."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {70, 70, RF_STORY_BATTLE, TRAINER_RF_STORY_8, 0x00000000, COMPOUND_STRING("Tobi quiere saber si su Pidgey\nestá listo para acompañarlo por\plas rutas. Te propone un combate\nde práctica en Paleta."), COMPOUND_STRING("Tobi recoge a su Pidgey con una\nsonrisa. No ganó, pero ahora\psabe qué entrenar antes de\nsalir."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {70, 71, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Con el camino seguro y el\nbotiquín listo, Tobi repartirá\pcada día. Ve a contárselo a\nMeli."), COMPOUND_STRING("Meli sonríe. Ahora podrá\ncontestar a su hermano sin\pesperar una semana."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {71, 70, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Meli te entrega una nota de\nagradecimiento para Tobi.\pLlévala a Paleta para cerrar la\nprimera semana del correo\pdiario."), COMPOUND_STRING("Tobi cuelga la nota junto a su\npuerta. El correo de Paleta ya\pno depende de un solo par de\npiernas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {73, 75, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Gema quiere enseñar geología\nfuera del museo. Nita conoce\phistorias de la vieja cantera;\npregúntale si quiere participar."), COMPOUND_STRING("Nita acepta encantada. Su abuela\ncontaba que cada veta de la\pcantera tenía un nombre."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {75, 75, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Nita dice que muchos visitantes\nconfunden a los Geodude con\ppiedras. Observa uno en Ruta 3 o\nen Monte Moon para contarles\pcómo distinguirlos."), COMPOUND_STRING("Nita apunta tus observaciones.\nLa visita empezará enseñando que\pno todas las piedras están\nquietas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {75, 74, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lázaro recorre la Ruta 3\nbuscando piedras curiosas. Gema\pquiere que guíe la parte\nexterior de la visita."), COMPOUND_STRING("Lázaro acepta con una condición:\nnadie se lleva piedras a casa.\pLas fotos bastan."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {74, 74, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("Lázaro quiere comprobar que\nsabes explicar la regla de la\pvisita. Responde a sus preguntas\nantes de que la pruebe con los\pniños."), COMPOUND_STRING("Lázaro aplaude. Has entendido\nque el mejor recuerdo de una\proca es dejarla en su sitio."), sPuzzle_107, 3, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {74, 73, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Los grupos pasarán por zonas con\nmuchos Zubat. Gema necesita dos\pRepelentes para que los\nvisitantes no se asusten."), COMPOUND_STRING("Gema guarda los Repelentes en la\nmochila de la visita. Nadie\ptendrá que correr por la cueva."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {73, 75, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Todo está preparado. Ve a avisar\na Nita: ella abrirá la visita\pcon la historia de su abuela."), COMPOUND_STRING("Nita ensaya en voz alta. La\nhistoria de la cantera emociona\pincluso a quien la cuenta."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {75, 74, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("La primera visita fue un éxito.\nLázaro quiere saber qué\ppreguntaron los niños para\npreparar la siguiente."), COMPOUND_STRING("Lázaro anota las preguntas. La\nmás repetida: si las piedras\ptambién tienen familia."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {74, 73, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lázaro te entrega sus notas para\nGema. Con ellas el museo podrá\prepetir la visita cada mes."), COMPOUND_STRING("Gema cuelga un mapa nuevo en el\nmuseo: la mitad de las piezas\psiguen fuera, donde deben estar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {76, 76, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Celia estudia el comportamiento\nde los Clefairy y necesita\payuda. Encuéntrala en la primera\nplanta de Monte Moon."), COMPOUND_STRING("Celia te cuenta que alguien ha\nestado recogiendo piedras\plunares y los Clefairy están\ninquietos."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {76, 76, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Celia quiere saber si los\nClefairy siguen saliendo pese a\plas molestias. Basta con ver\nuno."), COMPOUND_STRING("Celia respira aliviada. Siguen\nallí, aunque más escondidos que\pantes."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {76, 77, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Celia sospecha de un\ncoleccionista que vive junto a\pla Ruta 4. Habla con él antes de\nsacar conclusiones."), COMPOUND_STRING("Rufo admite que recogía piedras\nlunares, pero dice que dejó de\phacerlo hace semanas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {77, 77, RF_STORY_BATTLE, TRAINER_RF_STORY_9, 0x00000000, COMPOUND_STRING("Rufo quiere demostrar que no\ntiene nada que esconder. Propone\pun combate: si ganas, te\nenseñará su colección."), COMPOUND_STRING("Rufo abre una caja con doce\npiedras lunares. Las guardó\pporque no sabía a quién\ndevolverlas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {77, 76, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Rufo quiere devolver las\npiedras, pero no sabe dónde.\pLleva una Piedra Lunar a Celia\ncomo gesto de buena voluntad."), COMPOUND_STRING("Celia examina la piedra. Ahora\ntoca decidir qué hacer con las\pdemás."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {76, 76, RF_STORY_CHOICE, 0, 0x00000000, COMPOUND_STRING("Las piedras podrían ir al museo\nde Plateada, donde la gente\paprendería de ellas, o volver al\nmonte con los Clefairy. Celia\pquiere tu opinión."), COMPOUND_STRING("Celia decide devolver las\npiedras al monte. Los Clefairy\pvolverán a bailar alrededor de\nellas."), NULL, 0, NULL, RF_STORY_CHOICE_PIEDRA_AL_MUSEO, COMPOUND_STRING("Celia pregunta: ¿llevamos las\npiedras al museo?"), NULL, COMPOUND_STRING("Celia decide llevar las piedras\nal museo, con una cartela que\pexplica de dónde vienen y por\nqué no deben recogerse más.")},
    {76, 77, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Rufo espera en la Ruta 4. Ve a\ncontarle qué se hará con su\pcolección."), COMPOUND_STRING("Rufo asiente. Le alivia saber\nque las piedras tendrán un\pdestino pensado."), NULL, 0, NULL, RF_STORY_CHOICE_PIEDRA_AL_MUSEO, NULL, NULL, COMPOUND_STRING("Rufo se ofrece a guiar visitas\nen el museo. Dice que conoce\pcada piedra por su nombre.")},
    {77, 76, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Rufo te pide que lleves sus\nnotas a Celia: dónde encontró\pcada piedra."), COMPOUND_STRING("Celia completa su mapa. El monte\nvuelve a estar en calma y Rufo\pya no colecciona: observa."), NULL, 0, NULL, RF_STORY_CHOICE_PIEDRA_AL_MUSEO, NULL, NULL, COMPOUND_STRING("Celia completa la ficha del\nmuseo con las notas de Rufo.\pCada piedra expuesta lleva el\nnombre del lugar donde estuvo.")},
    {78, 79, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Pilar organiza la feria de\nCeleste y necesita a alguien que\previse la meta de la carrera en\nla Ruta 24."), COMPOUND_STRING("Arturo enseña la meta: un\nbanderín junto al puente. La\pcarrera empieza en la plaza de\nCeleste."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {79, 79, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Arturo quiere colocar carteles\nsobre los Pokémon de la ruta\ppara que los corredores no los\nmolesten. Registra dos capturas\pallí."), COMPOUND_STRING("Arturo dibuja los carteles. Los\ncorredores sabrán que la hierba\pde la ruta tiene vecinos."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {79, 80, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Dana vende bebidas en la feria\npero se ha quedado sin\pprovisiones. Búscala en la Ruta\n25."), COMPOUND_STRING("Dana cuenta que necesita una\nLimonada para preparar la receta\pde la feria."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {80, 80, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Dana quiere probar su receta\nantes de la feria. Entrégale una\pLimonada."), COMPOUND_STRING("Dana prueba la receta y pone\ncara seria. Luego sonríe: está\pperfecta."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {78, 79, RF_STORY_RACE, 0, 0x00000000, COMPOUND_STRING("Pilar quiere comprobar que la\ncarrera es segura. Sal desde la\pplaza y llega hasta Arturo, en\nla Ruta 24, en menos de 40\psegundos."), COMPOUND_STRING("Arturo detiene el cronómetro. El\nrecorrido es seguro y divertido;\pla feria puede empezar."), NULL, 0, &sRace_124, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {79, 79, RF_STORY_BATTLE, TRAINER_RF_STORY_10, 0x00000000, COMPOUND_STRING("Arturo quiere abrir la feria con\nun combate de exhibición. Te\pelige como rival."), COMPOUND_STRING("El público aplaude a los dos. En\nesta feria nadie pierde del\ptodo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {79, 78, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("La meta, los carteles y la\nlimonada están listos. Ve a\pavisar a Pilar."), COMPOUND_STRING("Pilar abre la feria con un\ndiscurso corto: gana quien\pdisfruta y quien deja disfrutar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {78, 80, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("La feria termina. Dana te espera\nen la Ruta 25 con la última\plimonada."), COMPOUND_STRING("Dana brinda por la próxima\nferia. Pilar ya ha reservado la\pplaza para el año que viene."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {82, 81, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Irma quiere escribir sobre el\npuerto para el boletín del Club\pde Fans. Ramón trabaja en el\nmuelle desde hace veinte años."), COMPOUND_STRING("Ramón acepta hablar, pero solo\nsi lo acompañas un día de\ptrabajo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {81, 81, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Los Machop del muelle trabajan\nmucho. Ramón te pide dos\pSuperpociones para que descansen\nbien."), COMPOUND_STRING("Ramón reparte las Superpociones.\nLos Machop del muelle se lo\pagradecen a su manera."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {81, 83, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Ramón dice que Kiko conoce el\nmejor punto para ver los barcos.\pBúscalo en la Ruta 11."), COMPOUND_STRING("Kiko te enseña su farola. Dice\nque desde allí se ven los barcos\pque llegan de noche."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {83, 83, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Kiko quiere incluir en el\nboletín a los Pokémon de la\pruta. Registra dos capturas\nallí."), COMPOUND_STRING("Kiko anota los nombres. El\nboletín tendrá su propia sección\pde vecinos."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {83, 83, RF_STORY_BATTLE, TRAINER_RF_STORY_11, 0x00000000, COMPOUND_STRING("Kiko quiere aparecer en el\nboletín con una historia propia.\pTe desafía a un combate."), COMPOUND_STRING("Kiko sonríe aunque pierda. Dice\nque la historia será buena\pigualmente."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {83, 82, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Con las historias de Ramón y\nKiko, Irma ya puede escribir el\pboletín. Llévale las notas."), COMPOUND_STRING("Irma lee las notas con atención.\nLe faltan las palabras del\ppropio Ramón."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {82, 81, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Irma quiere cerrar el boletín\ncon una pregunta: qué le diría\pRamón a quien empieza a trabajar\nen el puerto."), COMPOUND_STRING("Ramón piensa un rato. Responde\nque el mar enseña a esperar, y\pque esperar también es trabajar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {81, 82, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lleva la respuesta de Ramón al\nClub de Fans. Irma cerrará el\pboletín con ella."), COMPOUND_STRING("El boletín se agota en una\nmañana. Ramón guarda un ejemplar\pjunto a su caja de herramientas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {85, 85, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Ari cultiva un huerto junto a la\nCueva Diglett. Algo está\premoviendo su tierra cada noche."), COMPOUND_STRING("Ari sospecha de los Diglett,\npero no quiere echarlos. Quiere\pentenderlos."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {85, 85, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Ari quiere confirmar que son\nDiglett. Observa uno en la\pcueva."), COMPOUND_STRING("Ari ríe. Son Diglett, y su\ntierra está más esponjosa que\pnunca."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {85, 84, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lope mide los túneles de la\ncueva. Ari quiere saber si los\ptúneles llegan hasta su huerto."), COMPOUND_STRING("Lope confirma que un túnel nuevo\npasa bajo el huerto. Los Diglett\pbuscan raíces blandas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {84, 84, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("Lope explica cómo trabajan los\nDiglett y quiere saber si lo has\pentendido."), COMPOUND_STRING("Lope asiente. Quien entiende a\nlos Diglett deja de verlos como\pplaga."), sPuzzle_139, 3, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {84, 85, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Lope sugiere que Ari plante\nbayas en el borde del huerto\ppara los Diglett. Llévale tres\nBayas Aranja."), COMPOUND_STRING("Ari planta las bayas junto al\ntúnel. Los Diglett tendrán su\ppropio rincón."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {85, 84, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Ari quiere que Lope dibuje el\ntúnel en su mapa para no pisarlo\pal plantar."), COMPOUND_STRING("Lope marca el túnel con una\nlínea verde. Será el primer mapa\pcon un huerto dentro."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {84, 84, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Lope quiere medir el túnel\nnuevo, pero algunos Pokémon lo\pdefienden. Gana tres combates\ncontra salvajes para que pueda\ptrabajar."), COMPOUND_STRING("Lope termina la medición. Los\nPokémon vuelven a su sitio en\pcuanto él se aparta."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {84, 85, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lope te da el mapa terminado\npara Ari. Con él sabrá dónde\pplantar sin dañar los túneles."), COMPOUND_STRING("Ari cuelga el mapa en la puerta\ndel huerto. Las cosechas\pmejoran; los Diglett, también."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {86, 86, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("La Ruta 10 lleva semanas sin\nluz. Volta trabajó en la Central\py cree saber por qué."), COMPOUND_STRING("Volta explica que la Central\nfunciona con la ayuda de Pokémon\peléctricos que se han ido."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {86, 87, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Chispa entrena Pokémon\neléctricos en la Ruta 9. Volta\pquiere pedirle consejo."), COMPOUND_STRING("Chispa dice que los Pokémon\neléctricos se fueron porque la\pCentral estaba demasiado\nruidosa."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {87, 87, RF_STORY_BATTLE, TRAINER_RF_STORY_12, 0x00000000, COMPOUND_STRING("Chispa solo ayuda a quien conoce\nbien a los Pokémon eléctricos.\pTe reta a un combate."), COMPOUND_STRING("Chispa se rasca el pelo, que se\npone aún más de punta. Acepta\payudar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {87, 87, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Chispa quiere saber qué especies\neléctricas hay cerca. Registra\ptres capturas de tipo Eléctrico."), COMPOUND_STRING("Chispa repasa tu lista. Hay\nsuficientes Pokémon eléctricos\ppara una Central tranquila."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {87, 86, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Chispa propone apagar las\nmáquinas viejas y dejar solo las\psilenciosas. Llévale la idea a\nVolta."), COMPOUND_STRING("Volta asiente. Con menos ruido,\nlos Pokémon podrían volver."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {86, 86, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Volta revisará las máquinas, y a\nveces dan calambrazos. Te pide\pdos Antiparalizadores para el\nbotiquín."), COMPOUND_STRING("Volta guarda los\nAntiparalizadores. Ya puede\ptrabajar sin miedo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {86, 87, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Volta ha apagado las máquinas\nruidosas. Ve a contárselo a\pChispa."), COMPOUND_STRING("Chispa sonríe: sus Pokémon ya\nnotan la Central más tranquila."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {87, 86, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Chispa te da su lista de\nespecies para Volta. Con ella\psabrán quién vive en la Central."), COMPOUND_STRING("La Ruta 10 vuelve a tener luz\npor la noche. En la Central, los\pPokémon eléctricos duermen sin\nruido."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {88, 89, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lira quiere tocar música en la\nTorre Pokémon para quienes la\pvisitan. Pregunta a Basilio qué\nopina."), COMPOUND_STRING("Basilio duda. Algunos visitantes\nprefieren el silencio; otros\pquizá agradecerían la música."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {89, 90, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Basilio sugiere preguntar a\nVela, que perdió a su Growlithe\phace un año y visita la torre a\nmenudo."), COMPOUND_STRING("Vela cuenta que a veces el\nsilencio de la torre le pesa\pdemasiado."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {90, 90, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Vela tiene miedo de los Gastly\nde la torre. Cree que, si\palguien los observa y le cuenta\ncómo son, perderá el miedo."), COMPOUND_STRING("Vela escucha tu descripción. Los\nGastly solo juegan; quizá\ptambién acompañan."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {90, 89, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Vela quiere dejar algo en la\nentrada de la torre. Basilio\psugiere una Muñeca Poké, que los\nniños dejan como recuerdo."), COMPOUND_STRING("Basilio coloca la muñeca junto a\nla puerta. Vela sonríe por\pprimera vez en mucho tiempo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {89, 88, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Basilio y Vela tienen opiniones\ndistintas sobre la música. Lira\pquiere escucharlas antes de\ndecidir."), COMPOUND_STRING("Lira entiende las dos posturas.\nTe pide ayuda para decidir."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {88, 88, RF_STORY_CHOICE, 0, 0x00000000, COMPOUND_STRING("Lira podría tocar dentro de la\ntorre o solo en la plaza del\ppueblo, dejando la torre en\nsilencio."), COMPOUND_STRING("Lira decide tocar en la plaza.\nLa torre conserva su silencio, y\pquien quiera música sabe dónde\nencontrarla."), NULL, 0, NULL, RF_STORY_CHOICE_MUSICA_EN_LA_TORRE, COMPOUND_STRING("Lira pregunta: ¿toco dentro de\nla Torre Pokémon?"), NULL, COMPOUND_STRING("Lira decide tocar en la torre\nuna vez por semana, muy suave,\pen la planta de entrada.")},
    {88, 90, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lira ha compuesto una canción\npara Growlithe. Ve a invitar a\pVela."), COMPOUND_STRING("Vela escucha la canción con los\nojos cerrados. Dice que ya sabe\pcómo despedirse."), NULL, 0, NULL, RF_STORY_CHOICE_MUSICA_EN_LA_TORRE, NULL, NULL, COMPOUND_STRING("Vela escucha la canción en la\nentrada de la torre. Dice que,\ppor primera vez, el lugar no le\npesa.")},
    {90, 88, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Vela te pide que le des las\ngracias a Lira. Quiere que la\pcanción se toque cada año."), COMPOUND_STRING("Lira promete tocarla cada año.\nLavanda tiene ahora una canción\ppropia para recordar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {91, 91, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Flora cuida los jardines de\nAzulona, pero este año casi no\pllegan Pokémon a las flores."), COMPOUND_STRING("Flora sospecha que faltan\nplantas que den néctar. Necesita\payuda para elegir cuáles."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {91, 91, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Flora quiere saber qué Pokémon\nde tipo Planta hay cerca para\pelegir flores que les gusten."), COMPOUND_STRING("Flora repasa tu lista. Ya sabe\nqué plantar en cada parterre."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {91, 92, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Genaro vende semillas en la Ruta\n7. Flora quiere encargarle\pvariedades de néctar."), COMPOUND_STRING("Genaro tiene las semillas, pero\npide a cambio algo con que regar\plos brotes."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {92, 92, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Genaro necesita agua limpia para\nque las semillas germinen antes\pde venderlas. Entrégale dos\nAguas Frescas."), COMPOUND_STRING("Genaro riega los brotes con\ncuidado. En unos días estarán\plistos para Flora."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {92, 93, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Genaro dice que Aroa sabe qué\nflores atraen a más Pokémon:\phace perfumes con sus pétalos."), COMPOUND_STRING("Aroa recomienda flores de olor\nsuave. Las de olor fuerte\pasustan a los Oddish."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {93, 93, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("Aroa quiere comprobar que\nentiendes el jardín antes de dar\psu receta."), COMPOUND_STRING("Aroa sonríe. Entiendes que un\njardín es un lugar de paso, no\puna vitrina."), sPuzzle_165, 3, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {93, 91, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Con las semillas de Genaro y el\nconsejo de Aroa, Flora puede\preplantar los parterres."), COMPOUND_STRING("Flora planta las flores nuevas.\nDeja un rincón sin podar, como\precomendó Aroa."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {91, 92, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Una semana después, los\nparterres están llenos de\pPokémon. Ve a contárselo a\nGenaro."), COMPOUND_STRING("Genaro ríe y promete reservar\nsemillas para el año que viene.\pAzulona vuelve a oler a flores."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {94, 94, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Dimas trabajó en el casino\ndurante años. Quiere saber qué\pfue de los Pokémon que se daban\ncomo premio."), COMPOUND_STRING("Dimas recuerda nombres y fechas.\nCree que muchos Pokémon de\ppremio nunca tuvieron un hogar\nestable."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {94, 95, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Dimas tiene la ficha de un\nPorygon entregado hace años. La\pdueña, Rocío, vive junto a la\nRuta 8."), COMPOUND_STRING("Rocío cuida bien a su Porygon,\npero siempre se preguntó de\pdónde venía."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {95, 95, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Rocío quiere saber cómo es un\nPorygon sano para compararlo con\pel suyo. Observa uno."), COMPOUND_STRING("Rocío compara tus notas con su\nPorygon. Está sano y feliz."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {95, 94, RF_STORY_BATTLE, TRAINER_RF_STORY_13, 0x00000000, COMPOUND_STRING("Dimas quiere comprobar que sabes\ntratar a los Pokémon antes de\pcompartir los archivos del\ncasino."), COMPOUND_STRING("Dimas guarda sus Pokémon y abre\nel archivo. Son cientos de\pfichas sin seguimiento."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {94, 94, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Dimas quiere guardar una Poké\nBall junto a cada ficha que\pencuentre un dueño, como\nrecordatorio."), COMPOUND_STRING("Dimas coloca las Poké Balls\njunto a las fichas. Cada una\pespera un nombre."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {94, 94, RF_STORY_CHOICE, 0, 0x00000000, COMPOUND_STRING("Dimas propone pedir que el\ncasino deje de entregar Pokémon\pcomo premio y dé objetos en su\nlugar."), COMPOUND_STRING("Dimas presenta la propuesta. El\nmostrador de premios solo\pentregará objetos."), NULL, 0, NULL, RF_STORY_CHOICE_CASINO_CERRADO, COMPOUND_STRING("Dimas pregunta: ¿pedimos que\ncierren el mostrador?"), NULL, COMPOUND_STRING("Dimas decide que el mostrador\nsiga, pero con una ficha de\pseguimiento para cada Pokémon\nentregado.")},
    {94, 95, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Rocío quiere saber qué pasará\ncon los Pokémon de premio a\ppartir de ahora."), COMPOUND_STRING("Rocío se alegra. Ningún Pokémon\nsaldrá de una máquina sin saber\pa dónde va."), NULL, 0, NULL, RF_STORY_CHOICE_CASINO_CERRADO, NULL, NULL, COMPOUND_STRING("Rocío se ofrece a visitar a cada\nPokémon entregado durante el\pprimer mes.")},
    {95, 94, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Rocío firma la ficha de su\nPorygon. Llévasela a Dimas para\pcerrar el primer caso."), COMPOUND_STRING("Dimas archiva la ficha con una\nnota: “hogar encontrado”. Es la\pprimera de muchas."), NULL, 0, NULL, RF_STORY_CHOICE_CASINO_CERRADO, NULL, NULL, COMPOUND_STRING("Dimas archiva la ficha y abre\notra en blanco. El seguimiento\pempieza hoy.")},
    {96, 96, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Kai es el aprendiz más joven del\nDojo. Dice que quiere aprender\palgo más que a barrer."), COMPOUND_STRING("Kai cuenta que una entrenadora\nde fuera pidió entrar y el Dojo\pla rechazó. Le pareció injusto."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {96, 97, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Mei entrena sus Pokémon de tipo\nLucha sin maestro. Kai quiere\pconocerla."), COMPOUND_STRING("Mei duda. No quiere volver a\npedir permiso para que la\prechacen."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {97, 97, RF_STORY_BATTLE, TRAINER_RF_STORY_15, 0x00000000, COMPOUND_STRING("Mei quiere comprobar si su\nentrenamiento sirve. Te reta a\pun combate."), COMPOUND_STRING("Mei respira hondo. Ha aprendido\nsola más de lo que creía."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {97, 97, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Mei quiere enseñar a Kai qué\nPokémon de tipo Lucha viven\plibres en Kanto. Registra dos\ncapturas."), COMPOUND_STRING("Mei anota las especies. Le\nservirán para explicar su\pestilo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {97, 96, RF_STORY_BATTLE, TRAINER_RF_STORY_14, 0x00000000, COMPOUND_STRING("Kai quiere demostrar al maestro\nque ya sabe combatir. Te pide un\pcombate en el Dojo."), COMPOUND_STRING("El maestro observa en silencio.\nAl terminar, asiente una vez."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {96, 96, RF_STORY_CHOICE, 0, 0x00000000, COMPOUND_STRING("Kai quiere pedir que el Dojo\nabra un día a la semana para\pentrenadores de fuera, como Mei."), COMPOUND_STRING("El maestro acepta. Los sábados,\nel Dojo abrirá las puertas."), NULL, 0, NULL, RF_STORY_CHOICE_DOJO_ABIERTO, COMPOUND_STRING("Kai pregunta: ¿propongo abrir el\nDojo a gente de fuera?"), NULL, COMPOUND_STRING("Kai decide no pedirlo aún.\nPropondrá que él mismo entrene\pcon Mei fuera del Dojo.")},
    {96, 97, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Kai quiere que Mei sea la\nprimera en saberlo."), COMPOUND_STRING("Mei no se lo cree hasta que lo\nrepites. El sábado estará allí."), NULL, 0, NULL, RF_STORY_CHOICE_DOJO_ABIERTO, NULL, NULL, COMPOUND_STRING("Mei acepta entrenar con Kai en\nel parque. Dice que así ninguno\ptendrá que pedir permiso.")},
    {97, 96, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Mei te da su cinturón gastado\npara Kai: el primer regalo entre\pcompañeros de entrenamiento."), COMPOUND_STRING("Kai guarda el cinturón junto a\nla escoba. Ahora entrena y\pbarre, y no le importa."), NULL, 0, NULL, RF_STORY_CHOICE_DOJO_ABIERTO, NULL, NULL, COMPOUND_STRING("Kai cuelga el cinturón en el\nparque, en la rama donde\pentrenan cada tarde.")},
    {98, 98, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Pesca pesca en el puente de la\nRuta 12. Desde que se fue\pSnorlax, la ruta tiene más paso\ny más ruido."), COMPOUND_STRING("Pesca quiere poner carteles para\nque la gente no moleste a los\pPokémon del agua."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {98, 98, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Pesca quiere saber qué especies\nviven en el agua de la ruta.\pRegistra dos capturas allí."), COMPOUND_STRING("Pesca apunta las especies. Los\ncarteles tendrán dibujos de cada\puna."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {98, 99, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Nuria estudia el laberinto de\nvallas de la Ruta 13. Pesca\pquiere colocar allí uno de los\ncarteles."), COMPOUND_STRING("Nuria dice que las vallas cortan\nel paso de los Pokémon. Propone\pabrir un hueco."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {99, 99, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("Nuria quiere estar segura de\ndónde abrir el hueco sin dejar\psuelto a nadie."), COMPOUND_STRING("Nuria marca el hueco en su mapa.\nLos Pokémon podrán pasar y la\pgente no se perderá."), sPuzzle_187, 3, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {99, 100, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Nuria quiere avisar a los\nvecinos de la Ruta 14. Guille\pentrena Pidgeotto mensajeros."), COMPOUND_STRING("Guille acepta llevar los avisos,\npero necesita alimento para sus\pPidgeotto."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {100, 100, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Los Pidgeotto de Guille vuelan\nmejor con bayas. Entrégale tres\pBayas Aranja."), COMPOUND_STRING("Guille reparte las bayas. Los\nPidgeotto salen con los avisos\patados a la pata."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {100, 98, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Los Pidgeotto han vuelto con las\nrespuestas. Todos apoyan los\pcarteles."), COMPOUND_STRING("Pesca sonríe. Mañana colocarán\nel primero en el puente."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {98, 99, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Los carteles y el hueco están\nlistos. Ve a contárselo a Nuria."), COMPOUND_STRING("Nuria camina por el hueco nuevo.\nUn Oddish la adelanta sin\pmirarla siquiera."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {101, 101, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Ofelia lleva los registros del\nSafari. Cree que las redes y los\pcebos estresan a los Pokémon."), COMPOUND_STRING("Ofelia necesita datos para\nconvencer al Guarda. Te pide\payuda."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {101, 102, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Telmo fotografía el Safari desde\nfuera. Sus fotos podrían mostrar\pcómo reaccionan los Pokémon."), COMPOUND_STRING("Telmo enseña las fotos. Los\nPokémon huyen cada vez que\palguien lanza un cebo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {102, 102, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("A Telmo le falta una foto de\nChansey. Observa uno para\pdescribirle cómo se mueve."), COMPOUND_STRING("Telmo dibuja un Chansey a partir\nde tu descripción. Le servirá\phasta que consiga la foto."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {102, 103, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Marisa atiende a los Pokémon\nheridos del Safari. Ofelia\pquiere su testimonio."), COMPOUND_STRING("Marisa cuenta que muchos llegan\nagotados de huir de las redes."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {103, 103, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Marisa se ha quedado sin\nmedicinas. Entrégale dos\pSuperpociones."), COMPOUND_STRING("Marisa atiende a un Exeggcute\ncansado. Al rato, vuelve a\psaltar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {103, 101, RF_STORY_CHOICE, 0, 0x00000000, COMPOUND_STRING("Ofelia tiene los datos de Telmo\ny el testimonio de Marisa. Puede\pproponer prohibir las redes, o\nsolo limitarlas."), COMPOUND_STRING("Ofelia propone un Safari sin\nredes: solo paciencia y Poké\pBalls."), NULL, 0, NULL, RF_STORY_CHOICE_SAFARI_SIN_REDES, COMPOUND_STRING("Ofelia pregunta: ¿proponemos un\nSafari sin redes?"), NULL, COMPOUND_STRING("Ofelia propone limitar las redes\na dos por visita, con un\pdescanso obligatorio entre\nlanzamientos.")},
    {101, 103, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El Guarda ha aceptado la\npropuesta de Ofelia. Marisa\pquerrá saberlo."), COMPOUND_STRING("Marisa respira aliviada. Espera\nrecibir menos Pokémon agotados."), NULL, 0, NULL, RF_STORY_CHOICE_SAFARI_SIN_REDES, NULL, NULL, COMPOUND_STRING("Marisa acepta el término medio.\nDice que dos redes son mejor que\pveinte.")},
    {103, 101, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Un mes después, Marisa ha\nescrito un informe. Llévaselo a\pOfelia."), COMPOUND_STRING("El informe muestra menos Pokémon\nheridos. Ofelia lo cuelga en la\pCasa del Guarda."), NULL, 0, NULL, RF_STORY_CHOICE_SAFARI_SIN_REDES, NULL, NULL, COMPOUND_STRING("El informe muestra una mejora\npequeña pero clara. Ofelia lo\pcuelga junto a las normas\nnuevas.")},
    {105, 105, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lucía organiza una carrera\nciclista por la Pista Ciclista.\pQuiere que sea segura para\ntodos, Pokémon incluidos."), COMPOUND_STRING("Lucía necesita a alguien que\nrevise el recorrido y hable con\plos ciclistas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {105, 104, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Ciro conoce la pista mejor que\nnadie. Lucía quiere que sea el\pcapitán de la carrera."), COMPOUND_STRING("Ciro acepta, pero quiere\ncomprobar antes que sabes\pdefenderte en la pista."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {104, 104, RF_STORY_BATTLE, TRAINER_RF_STORY_16, 0x00000000, COMPOUND_STRING("Ciro te desafía a un combate\nantes de hablar de la carrera."), COMPOUND_STRING("Ciro se ríe. Dice que en la\npista no hay rivales, solo\pcompañeros que van más rápido o\nmás lento."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {104, 104, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Muchos Pokémon de tipo Veneno\nviven junto a la pista. Ciro\pquiere saber cuáles para avisar\na los corredores."), COMPOUND_STRING("Ciro anota las especies. Pondrá\ncarteles en las curvas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {104, 105, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Lucía quiere un botiquín en la\nmeta por si algún Pokémon o\pciclista se envenena."), COMPOUND_STRING("Lucía guarda los Antídotos en la\nmesa de la meta."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {104, 105, RF_STORY_RACE, 0, 0x00000000, COMPOUND_STRING("Ciro quiere comprobar el\nrecorrido. Sal de la Ruta 16 y\pllega hasta Lucía, en la Ruta\n18, en menos de un minuto."), COMPOUND_STRING("Lucía detiene el cronómetro. El\nrecorrido es bueno; solo falta\pdar la salida."), NULL, 0, &sRace_205, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {105, 104, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lucía quiere que Ciro dé la\nsalida. Llévale la bandera."), COMPOUND_STRING("Ciro agita la bandera. Los\nciclistas salen despacio en las\pcurvas con carteles."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {104, 105, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("La carrera ha terminado sin un\nsolo accidente. Lucía te espera\pen la meta."), COMPOUND_STRING("Lucía entrega una medalla a cada\nparticipante y otra a los\pPokémon de la cuneta, que se la\ncomen."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {106, 106, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Marina enseña a nadar con\nPokémon. Varias alumnas se han\pdesviado por corrientes nuevas."), COMPOUND_STRING("Marina quiere un mapa de\ncorrientes. Para eso necesita al\pvigía de la Ruta 20."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {106, 106, RF_STORY_BATTLE, TRAINER_RF_STORY_17, 0x00000000, COMPOUND_STRING("Marina solo trabaja con\nentrenadores que conocen el\pagua. Te reta a un combate."), COMPOUND_STRING("Marina asiente. Sabes moverte en\nel agua sin perder el norte."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {106, 107, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Bruno vigila las corrientes\ndesde una roca de la Ruta 20."), COMPOUND_STRING("Bruno conoce las corrientes,\npero le faltan datos de las\pespecies que las siguen."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {107, 107, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Las especies de tipo Agua siguen\nlas corrientes. Bruno quiere\psaber cuáles hay."), COMPOUND_STRING("Bruno marca en su mapa dónde vio\ncada especie. Las corrientes\pempiezan a tener forma."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {107, 107, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Los Seel de las Islas Espuma\nindican dónde está el agua fría.\pObserva uno."), COMPOUND_STRING("Bruno anota el dato. Donde hay\nSeel, la corriente baja del\pnorte."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {107, 107, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("Bruno quiere comprobar que\nsabrás explicar el mapa a las\palumnas de Marina."), COMPOUND_STRING("Bruno te da el mapa. Dice que lo\nexplicarás mejor que él."), sPuzzle_213, 3, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {107, 106, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lleva el mapa de Bruno a la\nescuela de Marina."), COMPOUND_STRING("Marina cuelga el mapa en la\norilla. Las alumnas lo estudian\pantes de entrar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {106, 107, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Las alumnas de Marina han\ncruzado sin desviarse. Ve a\pcontárselo a Bruno."), COMPOUND_STRING("Bruno sonríe desde su roca. Dice\nque el mar sigue mandando, pero\pahora se le entiende mejor."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {108, 108, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Adela vivió en Canela de niña.\nQuiere saber si la isla puede\pvolver a ser un hogar."), COMPOUND_STRING("Adela cuenta que el pueblo se\nfue tras la erupción. Ella\pquiere entender qué cambió."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {108, 109, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Ernesto estudia el volcán. Adela\nquiere saber si es seguro\preconstruir."), COMPOUND_STRING("Ernesto dice que el volcán está\ntranquilo, pero necesita datos\pde los Pokémon de fuego."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {109, 109, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Los Pokémon de tipo Fuego se\nalejan cuando el volcán se\pagita. Ernesto quiere saber\ncuántos hay."), COMPOUND_STRING("Ernesto repasa tu lista. Si los\nPokémon de fuego se quedan, el\pvolcán duerme."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {109, 108, RF_STORY_BATTLE, TRAINER_RF_STORY_18, 0x00000000, COMPOUND_STRING("Adela entrena Pokémon de fuego\ndesde niña. Quiere demostrar que\pel fuego también puede cuidar."), COMPOUND_STRING("Adela recoge a su Rapidash. Dice\nque el fuego que le quitó la\pcasa no es el mismo que la\nacompaña."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {108, 109, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Ernesto quiere un botiquín para\nquienes trabajen cerca del\pvolcán. Entrégale dos\nAntiquemar."), COMPOUND_STRING("Ernesto guarda los Antiquemar en\nla caja de la obra."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {109, 108, RF_STORY_CHOICE, 0, 0x00000000, COMPOUND_STRING("Adela puede impulsar la\nreconstrucción del pueblo, o\ppedir que la isla quede como\nreserva y memoria."), COMPOUND_STRING("Adela decide reconstruir. Canela\nvolverá a tener casas, con un\pplan de evacuación en cada\npuerta."), NULL, 0, NULL, RF_STORY_CHOICE_CANELA_RECONSTRUYE, COMPOUND_STRING("Adela pregunta: ¿reconstruimos\nel pueblo de Canela?"), NULL, COMPOUND_STRING("Adela decide que la isla sea una\nreserva. Las ruinas quedarán\pcomo memoria y refugio para los\nPokémon de fuego.")},
    {108, 109, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Ernesto quiere saber qué ha\ndecidido Adela para preparar sus\pmediciones."), COMPOUND_STRING("Ernesto instalará sensores en\ncada calle nueva. La isla\pavisará antes de despertar."), NULL, 0, NULL, RF_STORY_CHOICE_CANELA_RECONSTRUYE, NULL, NULL, COMPOUND_STRING("Ernesto se alegra. Una reserva\nle permitirá estudiar el volcán\psin prisas.")},
    {109, 108, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Ernesto te da su informe para\nAdela. Es la base de todo lo que\pvendrá."), COMPOUND_STRING("Adela guarda el informe junto a\nuna foto de su casa antigua.\pCanela tiene futuro otra vez."), NULL, 0, NULL, RF_STORY_CHOICE_CANELA_RECONSTRUYE, NULL, NULL, COMPOUND_STRING("Adela guarda el informe junto a\nuna foto de la isla. La reserva\pabrirá el próximo verano.")},
    {110, 110, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Silvia marca senderos con cintas\nporque cada semana se pierde\palgún niño en el bosque."), COMPOUND_STRING("Silvia dice que las cintas\ndesaparecen. Sospecha de los\pCaterpie, pero quiere\ncomprobarlo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {110, 110, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Silvia quiere confirmar que los\nCaterpie se comen las cintas.\pObserva uno."), COMPOUND_STRING("Silvia ríe. Las cintas son de\ntela vegetal; los Caterpie las\pconfunden con hojas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {110, 111, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Julio se perdió en el bosque de\nniño. Silvia quiere saber qué le\phabría ayudado."), COMPOUND_STRING("Julio recuerda que lo que más\nmiedo le dio fue no saber si iba\phacia dentro o hacia fuera."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {111, 110, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Julio sugiere marcar los árboles\ncon piedras pintadas en vez de\pcintas. Silvia necesitará\nRepelentes mientras trabaja."), COMPOUND_STRING("Silvia guarda los Repelentes.\nPodrá pintar piedras sin que la\pinterrumpan cada dos pasos."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {110, 110, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Silvia no quiere colocar piedras\ndonde anidan los Pokémon.\pRegistra dos capturas en el\nbosque para saber dónde viven."), COMPOUND_STRING("Silvia marca los nidos en su\nmapa. Las piedras irán lejos de\pellos."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {110, 110, RF_STORY_CHOICE, 0, 0x00000000, COMPOUND_STRING("Silvia puede abrir senderos\nanchos y señalizados, o solo\pponer piedras discretas en los\ncruces."), COMPOUND_STRING("Silvia abre senderos claros.\nNadie volverá a perderse, aunque\pel bosque parezca menos salvaje."), NULL, 0, NULL, RF_STORY_CHOICE_BOSQUE_CON_SENDEROS, COMPOUND_STRING("Silvia pregunta: ¿abrimos\nsenderos anchos?"), NULL, COMPOUND_STRING("Silvia solo marca los cruces con\npiedras pintadas. El bosque\psigue igual de denso, pero ahora\ntiene pistas.")},
    {110, 111, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Julio quiere saber si un niño\npodría cruzar el bosque ahora\psin perderse."), COMPOUND_STRING("Julio decide cruzar el bosque él\nmismo, por primera vez desde\pniño."), NULL, 0, NULL, RF_STORY_CHOICE_BOSQUE_CON_SENDEROS, NULL, NULL, COMPOUND_STRING("Julio estudia las piedras de los\ncruces. Dice que las habría\pseguido sin dudar.")},
    {111, 110, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Julio ha cruzado el bosque sin\nperderse. Ve a contárselo a\pSilvia."), COMPOUND_STRING("Silvia guarda la última cinta\ncomo recuerdo. Los Caterpie\ptendrán que buscar otra\nmerienda."), NULL, 0, NULL, RF_STORY_CHOICE_BOSQUE_CON_SENDEROS, NULL, NULL, COMPOUND_STRING("Silvia pinta una última piedra\ncon el nombre de Julio y la deja\pen el cruce donde se perdió.")},
    {113, 113, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Elena revisa medallas en la Ruta\n23. Ve a muchos entrenadores\pllegar agotados y sin consejo."), COMPOUND_STRING("Elena quiere crear una guía para\naspirantes. Necesita la voz de\palguien que haya fallado y\nvuelto."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {113, 112, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Hugo lleva años intentando\nllegar a la Liga. Elena cree que\psu experiencia vale más que una\nvictoria."), COMPOUND_STRING("Hugo acepta ayudar, pero antes\nquiere un combate: lleva mucho\psin enfrentarse a alguien\nfuerte."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {112, 112, RF_STORY_BATTLE, TRAINER_RF_STORY_19, 0x00000000, COMPOUND_STRING("Hugo quiere medir cuánto ha\nmejorado. Te desafía en la Ruta\p22."), COMPOUND_STRING("Hugo pierde, pero sonríe. Dice\nque ha aguantado más que nunca."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {112, 113, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Hugo dice que lo que más falta\nen la Calle Victoria son\pRevivir. Lleva dos a Elena para\nel puesto."), COMPOUND_STRING("Elena guarda los Revivir en el\nmostrador, para quien los\pnecesite."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {113, 113, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("Elena quiere comprobar que los\nconsejos de Hugo se entienden\pbien."), COMPOUND_STRING("Elena anota tus respuestas. La\nguía empieza a tener forma."), sPuzzle_236, 3, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {113, 113, RF_STORY_CHOICE, 0, 0x00000000, COMPOUND_STRING("Elena puede escribir una guía, o\npedir que Hugo acompañe a los\paspirantes hasta la entrada."), COMPOUND_STRING("Elena decide que Hugo acompañe a\nquien lo pida. Una persona vale\pmás que un folleto."), NULL, 0, NULL, RF_STORY_CHOICE_LIGA_CON_GUIA, COMPOUND_STRING("Elena pregunta: ¿pedimos a Hugo\nque acompañe a los aspirantes?"), NULL, COMPOUND_STRING("Elena escribe la guía con las\npalabras de Hugo. Cada aspirante\precibirá una copia en el puesto.")},
    {113, 112, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Hugo espera en la Ruta 22. Ve a\ncontarle qué ha decidido Elena."), COMPOUND_STRING("Hugo acepta. Dice que acompañar\na otros quizá sea su manera de\pllegar a la Liga."), NULL, 0, NULL, RF_STORY_CHOICE_LIGA_CON_GUIA, NULL, NULL, COMPOUND_STRING("Hugo se emociona al saber que\nsus palabras irán en la guía.\pFirma la primera página.")},
    {112, 113, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Hugo ha acompañado a su primer\naspirante. Lleva su informe a\pElena."), COMPOUND_STRING("Elena cuelga el informe en el\npuesto. El camino a la Liga ya\pno se recorre solo."), NULL, 0, NULL, RF_STORY_CHOICE_LIGA_CON_GUIA, NULL, NULL, COMPOUND_STRING("Elena reparte la primera guía.\nLa aspirante que la recibe\ppromete devolverla con una\npágina nueva.")},
    {115, 115, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Olivia vive junto a la Central\nEnergía. Cada noche oye zumbidos\py no sabe de dónde salen."), COMPOUND_STRING("Olivia sospecha que algo vive\ndentro. Quiere saber si es\ppeligroso."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {115, 114, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Pau revisa la Central de vez en\ncuando. Olivia quiere saber qué\pha visto."), COMPOUND_STRING("Pau dice que los zumbidos son de\nMagnemite y Voltorb que se\palimentan de la corriente que\nqueda."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {114, 114, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Pau quiere confirmar que los\nMagnemite siguen allí. Observa\puno."), COMPOUND_STRING("Pau anota la observación. Los\nMagnemite están bien, aunque más\pinquietos que antes."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {114, 114, RF_STORY_BATTLE, TRAINER_RF_STORY_20, 0x00000000, COMPOUND_STRING("Pau quiere saber si podrías\nayudarle a revisar las zonas más\ppeligrosas. Te reta a un\ncombate."), COMPOUND_STRING("Pau se coloca las gafas. Puedes\nacompañarle."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {114, 114, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Una máquina vieja da descargas.\nPau necesita dos\pAntiparalizadores antes de\nrepararla."), COMPOUND_STRING("Pau repara la máquina. Los\nzumbidos se vuelven más suaves."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {114, 114, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Algunos Pokémon defienden la\nzona de la máquina. Gana tres\pcombates para que Pau termine."), COMPOUND_STRING("Pau termina la reparación. Los\nPokémon vuelven a sus rincones."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {114, 115, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Ya sabes de dónde vienen los\nzumbidos. Ve a explicárselo a\pOlivia."), COMPOUND_STRING("Olivia se ríe. Lleva meses con\nmiedo de unos Pokémon que solo\pcomen chispas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {115, 114, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Olivia invita a Pau a cenar como\nagradecimiento. Llévale la\pinvitación."), COMPOUND_STRING("Pau acepta. Esa noche, los\nzumbidos suenan como música de\pfondo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {116, 116, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Celso recibe a los viajeros que\nllegan a Isla Uno. Quiere\ppreparar un recorrido de\nbienvenida."), COMPOUND_STRING("Celso necesita ayuda para elegir\nlas paradas del recorrido."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {116, 118, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Iker lleva el registro de\nviajeros. Sabe qué buscan\pquienes llegan."), COMPOUND_STRING("Iker dice que casi todos\npreguntan por las aguas termales\pdel Camino Candente."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {118, 117, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Greta conoce las aguas termales\nmejor que nadie. Iker quiere que\psea una parada del recorrido."), COMPOUND_STRING("Greta acepta, siempre que los\nvisitantes respeten a los\pPokémon que viven allí."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {117, 117, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Greta quiere que los visitantes\nsepan qué Pokémon viven en el\pCamino Candente. Registra dos\ncapturas allí."), COMPOUND_STRING("Greta dibuja un cartel con las\nespecies. Los visitantes sabrán\pa quién no molestar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {117, 117, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Después de las termas, los\nvisitantes necesitan beber.\pGreta te pide dos Aguas Frescas\npara el puesto."), COMPOUND_STRING("Greta coloca el agua junto a la\nentrada de las termas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {116, 117, RF_STORY_RACE, 0, 0x00000000, COMPOUND_STRING("Celso quiere saber cuánto se\ntarda del muelle a las termas.\pHazlo en menos de 90 segundos."), COMPOUND_STRING("Greta anota el tiempo. El\nrecorrido cabe en una mañana."), NULL, 0, &sRace_253, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {117, 116, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Greta ha completado la lista de\nparadas. Llévasela a Celso."), COMPOUND_STRING("Celso coloca el mapa del\nrecorrido en el muelle."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {116, 118, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El recorrido ya está listo. Iker\npodrá recomendarlo a cada\pviajero."), COMPOUND_STRING("Iker añade una línea a su\nregistro: “recorrido de\pbienvenida”. Nadie llegará sin\nsaber a dónde ir."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {119, 119, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lola tiene la tienda de Isla\nDos. Cada día pasan viajeros\ppreguntando por el Cabo Extremo."), COMPOUND_STRING("Lola cuenta que el camino al\ncabo es estrecho y algunos\pviajeros se pierden."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {119, 120, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Teodora vive en el cabo. Lola\nquiere saber qué opina de tanta\pvisita."), COMPOUND_STRING("Teodora quiere ayudar a los\nviajeros, pero teme que el cabo\ppierda su calma."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {120, 120, RF_STORY_BATTLE, TRAINER_RF_STORY_21, 0x00000000, COMPOUND_STRING("Teodora entrena a los tres\nPokémon iniciales de Kanto. Te\preta para ver si estás\npreparado."), COMPOUND_STRING("Teodora recoge a sus Pokémon.\nDice que entiendes por qué la\pgente viene hasta aquí."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {120, 119, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Teodora quiere que la tienda de\nLola tenga un botiquín para los\pviajeros que llegan agotados."), COMPOUND_STRING("Lola guarda las medicinas en el\nmostrador."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {119, 119, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("Lola quiere preparar un cartel\ncon consejos para los viajeros."), COMPOUND_STRING("Lola escribe el cartel con tus\nrespuestas."), sPuzzle_260, 3, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {119, 120, RF_STORY_CHOICE, 0, 0x00000000, COMPOUND_STRING("Teodora puede pedir que se\nensanche el camino al cabo, o\pdejarlo como está y señalizarlo."), COMPOUND_STRING("Teodora decide ensanchar el\ncamino. Los viajeros llegarán\pcon más facilidad."), NULL, 0, NULL, RF_STORY_CHOICE_CABO_ABIERTO, COMPOUND_STRING("Teodora pregunta: ¿ensanchamos\nel camino al cabo?"), NULL, COMPOUND_STRING("Teodora decide dejar el camino\nestrecho, con carteles. El cabo\pconservará su calma.")},
    {120, 119, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lola quiere saber qué pasará con\nel camino."), COMPOUND_STRING("Lola se alegra. Los viajeros\npodrán llegar sin miedo a\pperderse."), NULL, 0, NULL, RF_STORY_CHOICE_CABO_ABIERTO, NULL, NULL, COMPOUND_STRING("Lola pone su cartel junto al de\nTeodora. El camino seguirá\psiendo estrecho, pero claro.")},
    {119, 120, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lola te da un tarro de mermelada\npara Teodora como\pagradecimiento."), COMPOUND_STRING("Teodora prueba la mermelada\nmirando al mar. Dice que el cabo\pnunca ha estado mejor."), NULL, 0, NULL, RF_STORY_CHOICE_CABO_ABIERTO, NULL, NULL, COMPOUND_STRING("Teodora guarda la mermelada para\nlos viajeros que lleguen\pcansados. El cabo sigue en\ncalma.")},
    {122, 122, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Sol quiere aprender lo que sabía\nsu abuelo, pescador de la Ruta\p21."), COMPOUND_STRING("Sol tiene un cuaderno del\nabuelo, pero está lleno de\ppalabras que no entiende."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {122, 121, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Antón rema por la Ruta 21 desde\nhace décadas. Quizá entienda el\pcuaderno."), COMPOUND_STRING("Antón reconoce la letra del\nabuelo de Sol. Eran amigos."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {121, 121, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("Antón explica algunas palabras\ndel cuaderno. Quiere saber si\plas entiendes."), COMPOUND_STRING("Antón asiente. Ya puedes\nexplicárselo a Sol."), sPuzzle_266, 3, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {121, 121, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("El cuaderno nombra especies que\nAntón ya no ve. Registra dos\pcapturas de tipo Agua para\ncomparar."), COMPOUND_STRING("Antón compara tu lista con el\ncuaderno. Algunas especies han\pvuelto."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {121, 122, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Antón ha escrito notas al\nmargen. Lleva el cuaderno a Sol."), COMPOUND_STRING("Sol lee las notas emocionada.\nPor primera vez entiende a su\pabuelo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {122, 121, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Sol quiere aprender a pescar\ncomo su abuelo. Antón le\penseñará si le llevas una Caña\nBuena."), COMPOUND_STRING("Antón revisa la caña. Es buena;\nservirá para empezar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {121, 122, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Antón está listo para la primera\nclase. Ve a avisar a Sol."), COMPOUND_STRING("Sol corre hacia la playa con el\ncuaderno bajo el brazo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {122, 121, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Sol ha pescado su primer\nPokémon. Te pide que le des las\pgracias a Antón."), COMPOUND_STRING("Antón sonríe. Dice que el abuelo\nde Sol estaría orgulloso, y que\pel mar también."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {124, 124, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lucio lleva provisiones a una\ninvestigadora de las Islas\pEspuma. Necesita ayuda con el\núltimo envío."), COMPOUND_STRING("Lucio te da una caja para\nNoelia. Dice que te esperará\paquí."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {124, 123, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Noelia estudia el hielo de las\nIslas Espuma. Llévale la caja de\pLucio."), COMPOUND_STRING("Noelia abre la caja:\ninstrumentos de medida. Te pide\payuda con las mediciones."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {123, 123, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Los Seel necesitan hielo. Noelia\nquiere saber si siguen en las\pislas."), COMPOUND_STRING("Noelia respira aliviada. Siguen\nallí, aunque más al fondo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {123, 123, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Noelia quiere comparar cuántos\nPokémon de tipo Hielo hay hoy\pcon los de hace diez años."), COMPOUND_STRING("Noelia compara las listas. Hay\nmenos, pero no han desaparecido."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {123, 123, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Noelia pasa mucho frío. Te pide\ndos Antihielo para el botiquín."), COMPOUND_STRING("Noelia guarda los Antihielo.\nPodrá trabajar más horas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {123, 123, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("Noelia quiere comprobar que\nsabrás contar a Lucio lo que han\pmedido."), COMPOUND_STRING("Noelia te da sus notas. Lucio\nlas llevará a Carmín."), sPuzzle_277, 3, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {123, 124, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lucio llevará las notas al\ncontinente para que más gente\plas conozca."), COMPOUND_STRING("Lucio guarda las notas en una\ncaja impermeable."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {124, 123, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El laboratorio de Carmín ha\nrespondido: financiará la\pinvestigación de Noelia diez\naños más."), COMPOUND_STRING("Noelia lee la carta dos veces.\nEl hielo seguirá teniendo quien\plo cuide."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {125, 125, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Otto vendía Magikarp a precios\nabusivos. Ahora quiere saber qué\pfue de ellos."), COMPOUND_STRING("Otto guarda una lista de\ncompradores. Quiere encontrar al\pmenos uno."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {125, 125, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Otto no ha mirado un Magikarp de\nverdad en años. Quiere que le\pcuentes cómo es uno libre."), COMPOUND_STRING("Otto escucha en silencio. Nunca\nse había fijado en cómo nadan."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {125, 126, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Candela compró un Magikarp a\nOtto hace años. Él quiere\pdisculparse."), COMPOUND_STRING("Candela escucha la disculpa.\nDice que aquel Magikarp fue lo\pmejor que le pasó."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {126, 126, RF_STORY_BATTLE, TRAINER_RF_STORY_22, 0x00000000, COMPOUND_STRING("Candela quiere enseñar a Otto en\nqué se convirtió su Magikarp."), COMPOUND_STRING("El Gyarados de Candela ruge al\nterminar. Otto lo mira con la\pboca abierta."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {126, 125, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Candela dice que su secreto fue\nla paciencia. Lleva su consejo a\pOtto."), COMPOUND_STRING("Otto anota la palabra en su\nlista, junto al nombre de\pCandela."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {125, 125, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Otto quiere aprender a cuidar\nPokémon de agua antes de ayudar\pa otros. Registra dos capturas\npara enseñarle."), COMPOUND_STRING("Otto practica con tus consejos.\nSus manos ya no tiemblan al\ptocar el agua."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {125, 126, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Candela cuida un estanque para\nMagikarp abandonados. Otto\pquiere colaborar enviándole\nbayas."), COMPOUND_STRING("Candela echa las bayas al\nestanque. Los Magikarp saltan."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {126, 125, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Candela invita a Otto a ayudar\nen el estanque cada semana."), COMPOUND_STRING("Otto acepta. Ya no vende\nMagikarp: los cuida, sin prisa."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {127, 127, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Tere lleva la Guardería desde\nhace cuarenta años. Busca a\palguien que ayude a un aprendiz."), COMPOUND_STRING("Tere habla de Renzo, un joven\nque quiere criar Pokémon pero\ptiene miedo de equivocarse."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {127, 128, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Renzo vive en Isla Cuatro. Tere\nquiere que le cuentes cómo\ptrabajas con tus Pokémon."), COMPOUND_STRING("Renzo escucha con atención.\nPregunta si alguna vez has visto\pnacer un Pokémon."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {128, 128, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Renzo quiere oír de primera mano\ncómo es una eclosión. Haz\peclosionar un huevo."), COMPOUND_STRING("Renzo escucha tu relato sin\npestañear. Dice que ahora le da\pmenos miedo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {128, 127, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("Tere quiere comprobar que Renzo\nha entendido lo básico, y te\ppide que respondas por él."), COMPOUND_STRING("Tere asiente. Renzo está listo\npara su primer huevo."), sPuzzle_291, 3, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {127, 127, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Tere quiere preparar un botiquín\npara los recién nacidos.\pEntrégale dos Pociones."), COMPOUND_STRING("Tere guarda las Pociones junto a\nlas mantas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {127, 127, RF_STORY_CHOICE, 0, 0x00000000, COMPOUND_STRING("Tere puede abrir la Guardería a\nvisitas para enseñar a otros\pjóvenes, o mantenerla tranquila\ny formar solo a Renzo."), COMPOUND_STRING("Tere decide abrir las puertas\nlos domingos. Renzo será el\pguía."), NULL, 0, NULL, RF_STORY_CHOICE_GUARDERIA_ABIERTA, COMPOUND_STRING("Tere pregunta: ¿abrimos la\nGuardería a visitas?"), NULL, COMPOUND_STRING("Tere decide mantener la\nGuardería tranquila. Renzo\paprenderá a su lado, sin prisas\nni público.")},
    {127, 128, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Renzo espera fuera. Ve a\ncontarle lo que ha decidido\pTere."), COMPOUND_STRING("Renzo salta de alegría. Su\nprimer día como guía será el\pdomingo."), NULL, 0, NULL, RF_STORY_CHOICE_GUARDERIA_ABIERTA, NULL, NULL, COMPOUND_STRING("Renzo asiente, aliviado.\nPrefiere aprender sin público.")},
    {128, 127, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Renzo ha cuidado su primer huevo\nhasta la eclosión. Llévale su\pinforme a Tere."), COMPOUND_STRING("Tere lee el informe con una\nsonrisa. Ningún huevo es igual a\potro; ningún cuidador tampoco."), NULL, 0, NULL, RF_STORY_CHOICE_GUARDERIA_ABIERTA, NULL, NULL, COMPOUND_STRING("Tere guarda el informe en la\ncaja de los recuerdos. Renzo ya\pcuida solo.")},
    {130, 130, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Blanca esculpe hielo y quiere\norganizar un festival en Isla\pCuatro."), COMPOUND_STRING("Blanca necesita hielo de la\ncueva, pero no quiere dañarla.\pBusca al guía."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {130, 129, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Gil guía visitas a la cueva.\nBlanca quiere saber de dónde\psacar hielo sin dañarla."), COMPOUND_STRING("Gil dice que hay hielo que se\ndesprende solo cada primavera.\pSe puede recoger."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {129, 129, RF_STORY_BATTLE, TRAINER_RF_STORY_23, 0x00000000, COMPOUND_STRING("Gil solo lleva a la cueva a\nquien sabe moverse en el hielo.\pTe reta a un combate."), COMPOUND_STRING("Gil sonríe. Puedes acompañarle a\nrecoger hielo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {129, 129, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Gil quiere saber qué Pokémon de\nhielo viven cerca para no\pmolestarlos al recoger."), COMPOUND_STRING("Gil marca en su mapa dónde no\nrecoger."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {129, 130, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Gil ha recogido el hielo caído.\nLlévaselo a Blanca."), COMPOUND_STRING("Blanca toca el hielo con\ncuidado. Es perfecto:\ptransparente y frío."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {130, 130, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Blanca trabaja horas con hielo.\nTe pide dos Antihielo por si\palgún Pokémon se congela."), COMPOUND_STRING("Blanca guarda los Antihielo\njunto a sus cinceles."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {130, 129, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Las esculturas están listas.\nBlanca quiere que Gil sea el\pinvitado de honor."), COMPOUND_STRING("Gil acepta. Dice que nunca había\nvisto el hielo de su cueva con\pforma de Lapras."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {129, 130, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El festival ha terminado y las\nesculturas se derriten al sol.\pGil te pide que agradezcas a\nBlanca."), COMPOUND_STRING("Blanca mira cómo se derrite su\nLapras. Dice que así debe ser:\pel año que viene habrá otro."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {132, 132, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Los Miltank de Leandro se\nescapan a la Pradera cada día.\pQuiere poner cercas."), COMPOUND_STRING("Leandro sabe que Amapola no\nestará de acuerdo. Te pide que\phables con ella."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {132, 131, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Amapola cuida la Pradera. Teme\nque las cercas corten el paso de\plos Pokémon salvajes."), COMPOUND_STRING("Amapola propone otra idea: que\nlos Miltank pasten con los\psalvajes, pero con campanas."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {131, 131, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Amapola quiere saber qué Pokémon\nsalvajes comparten la Pradera\pcon los Miltank."), COMPOUND_STRING("Amapola apunta las especies. Hay\nsitio para todos."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {131, 132, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Amapola sugiere poner una\ncampana al Miltank que más se\pescapa. Lleva una Campana Alivio\na Leandro."), COMPOUND_STRING("Leandro cuelga la campana en el\ncuello de su Miltank más\pinquieto."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {132, 132, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Leandro quiere que alguien de\nfuera vea cómo se comportan sus\pMiltank en la Pradera."), COMPOUND_STRING("Leandro escucha tu relato. Sus\nMiltank parecen más tranquilos\pde lo que pensaba."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {132, 131, RF_STORY_CHOICE, 0, 0x00000000, COMPOUND_STRING("Leandro y Amapola deben decidir:\ndejar la Pradera sin cercas, con\pcampanas, o cercar solo una\nparte."), COMPOUND_STRING("Amapola decide no poner cercas.\nLas campanas bastan para saber\pdónde están los Miltank."), NULL, 0, NULL, RF_STORY_CHOICE_PRADERA_SIN_CERCAS, COMPOUND_STRING("Amapola pregunta: ¿dejamos la\nPradera sin cercas?"), NULL, COMPOUND_STRING("Amapola acepta una cerca baja en\nuna esquina. Los Pokémon\psalvajes pueden saltarla sin\nproblema.")},
    {131, 132, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Leandro espera en Isla Cinco. Ve\na contarle qué ha decidido\pAmapola."), COMPOUND_STRING("Leandro acepta. Mientras suene\nla campana, sabrá dónde están\psus Miltank."), NULL, 0, NULL, RF_STORY_CHOICE_PRADERA_SIN_CERCAS, NULL, NULL, COMPOUND_STRING("Leandro construye la cerca baja\ncon madera de la playa. Sus\pMiltank la ignoran, pero la\nrespetan.")},
    {132, 131, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Leandro te da una botella de\nLeche Mu-mu para Amapola, como\pagradecimiento."), COMPOUND_STRING("Amapola brinda con la leche. La\nPradera sigue abierta para\ptodos."), NULL, 0, NULL, RF_STORY_CHOICE_PRADERA_SIN_CERCAS, NULL, NULL, COMPOUND_STRING("Amapola brinda con la leche\njunto a la cerca baja. La\pPradera ha encontrado un\nequilibrio.")},
    {133, 133, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Irene trabaja en el Resort. Un\nhuésped ha pedido algo muy raro\py necesita ayuda."), COMPOUND_STRING("El huésped quiere ver un Pokémon\nde cada tipo antes de irse.\pIrene no sabe por dónde empezar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {133, 134, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Max hace recados para el Resort.\nIrene quiere que te ayude."), COMPOUND_STRING("Max dice que conoce a todos en\nlas islas. Puede ayudar, pero\pprimero quiere ponerte a prueba."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {134, 134, RF_STORY_BATTLE, TRAINER_RF_STORY_24, 0x00000000, COMPOUND_STRING("Max quiere comprobar que eres\nfiable antes de compartir sus\pcontactos."), COMPOUND_STRING("Max ríe. Eres de fiar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {134, 134, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Max propone empezar por lo\nfácil: tipo Normal. Registra\ptres capturas."), COMPOUND_STRING("Max apunta las especies. Una\nparte del encargo está lista."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {134, 133, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Max sugiere regalar al huésped\nuna Perla para que el encargo no\pparezca una lista de tareas."), COMPOUND_STRING("Irene envuelve la Perla con un\nlazo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {133, 133, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("El huésped quiere saber si de\nverdad conoces a los Pokémon\pantes de aceptar el regalo."), COMPOUND_STRING("El huésped aplaude. Dice que no\nhabía oído respuestas tan\psinceras en años."), sPuzzle_317, 3, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {133, 134, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("El huésped se va contento. Ve a\navisar a Max."), COMPOUND_STRING("Max sonríe. Dice que es el\nencargo más raro del año."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {134, 133, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Max reparte la propina contigo e\nIrene. Lleva su parte al Resort."), COMPOUND_STRING("Irene guarda la propina para el\npróximo encargo imposible."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {136, 136, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Nadia organiza una limpieza del\nCamino Acuático. Necesita\pvoluntarios."), COMPOUND_STRING("Nadia te presenta a Paco, que\nlimpia la costa cada día sin que\pnadie se lo pida."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {136, 135, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Paco sabe dónde se acumula la\nbasura. Nadia quiere su ayuda."), COMPOUND_STRING("Paco te enseña las calas donde\nel mar deja más restos."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {135, 135, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Paco quiere saber qué Pokémon\nviven en las calas para no\pmolestarlos al limpiar."), COMPOUND_STRING("Paco marca en su mapa las calas\ncon nidos."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {135, 136, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Algunos restos tienen sustancias\ntóxicas. Nadia quiere Antídotos\ppara los voluntarios."), COMPOUND_STRING("Nadia guarda los Antídotos en la\ncaseta de la asociación."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {136, 135, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Algunos Pokémon defienden las\ncalas. Gana tres combates para\pque los voluntarios trabajen\ntranquilos."), COMPOUND_STRING("Paco agradece la ayuda. Los\nvoluntarios ya pueden trabajar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {135, 135, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("Paco quiere comprobar que sabrás\nexplicar las normas a los\pvoluntarios."), COMPOUND_STRING("Paco asiente. Ya puedes dirigir\nun grupo."), sPuzzle_325, 3, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {135, 136, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Paco ha contado todo lo que se\nha recogido. Lleva el informe a\pNadia."), COMPOUND_STRING("Nadia lee el informe con la boca\nabierta. Han limpiado tres calas\penteras."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {136, 135, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("La asociación ha votado dar a\nPaco una medalla. Llévasela."), COMPOUND_STRING("Paco se ruboriza. Dice que la\nmedalla es para el mar, que\pdevuelve todo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {137, 137, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Dora cree que bajo el valle hay\nuna construcción antigua. Quiere\pexcavar, pero tiene dudas."), COMPOUND_STRING("Dora sabe que los vecinos de\nIsla Seis consideran el valle un\plugar sagrado."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {137, 138, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Mateo es de una familia antigua\nde la isla. Dora quiere saber\pqué opina."), COMPOUND_STRING("Mateo cuenta que su abuela\nhablaba de Pokémon que dormían\pen el valle."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {138, 138, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Mateo cree que los Pokémon de la\nleyenda son Unown. Observa uno."), COMPOUND_STRING("Mateo escucha tu descripción.\nDice que su abuela tenía razón."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {138, 137, RF_STORY_BATTLE, TRAINER_RF_STORY_25, 0x00000000, COMPOUND_STRING("Dora entrena Pokémon revividos\nde fósiles. Quiere demostrar a\pMateo que respeta el pasado."), COMPOUND_STRING("Dora recoge a sus Pokémon. Mateo\nla mira de otra manera."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {137, 138, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Dora quiere dejar una ofrenda en\nel valle, como hacía la abuela\pde Mateo."), COMPOUND_STRING("Mateo coloca la Esquirla en la\nentrada del valle."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {138, 137, RF_STORY_CHOICE, 0, 0x00000000, COMPOUND_STRING("Dora puede excavar con cuidado y\ncon los vecinos, o renunciar y\pdocumentar solo lo que se ve."), COMPOUND_STRING("Dora decide excavar con los\nvecinos. Mateo dirigirá a los\pvoluntarios de la isla."), NULL, 0, NULL, RF_STORY_CHOICE_VALLE_EXCAVADO, COMPOUND_STRING("Dora pregunta: ¿excavamos el\nvalle?"), NULL, COMPOUND_STRING("Dora decide no excavar.\nDocumentará el valle tal como\pestá, con dibujos y sin palas.")},
    {137, 138, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Mateo espera en Isla Seis. Ve a\ncontarle qué ha decidido Dora."), COMPOUND_STRING("Mateo acepta. Dice que su abuela\nquerría saber qué hay ahí abajo."), NULL, 0, NULL, RF_STORY_CHOICE_VALLE_EXCAVADO, NULL, NULL, COMPOUND_STRING("Mateo se emociona. Dice que el\nvalle seguirá descansando, como\pdebe.")},
    {138, 137, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Mateo te da un dibujo antiguo de\nsu abuela para Dora. Muestra el\pvalle hace cien años."), COMPOUND_STRING("Dora compara el dibujo con el\nvalle actual. Ha cambiado poco:\palguien siempre lo ha cuidado."), NULL, 0, NULL, RF_STORY_CHOICE_VALLE_EXCAVADO, NULL, NULL, COMPOUND_STRING("Dora coloca el dibujo en la\nprimera página de su cuaderno.\pEl valle tendrá su historia\nescrita.")},
    {139, 139, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Vega organiza los retos de la\nTorre. Le preocupa que solo\pvengan entrenadores expertos."), COMPOUND_STRING("Vega quiere atraer a novatos,\npero no sabe qué los frena."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {139, 140, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Pipo quiere subir a la Torre\npero no se atreve. Vega quiere\psaber por qué."), COMPOUND_STRING("Pipo confiesa que le da miedo\nperder delante de todos."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {140, 139, RF_STORY_BATTLE, TRAINER_RF_STORY_26, 0x00000000, COMPOUND_STRING("Vega quiere mostrar a Pipo que\nperder contra alguien fuerte no\pes una vergüenza. Te reta\ndelante de él."), COMPOUND_STRING("Gane quien gane, Vega se acerca\na Pipo y le explica lo que ha\paprendido del combate."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {139, 140, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Vega sugiere que Pipo entrene\ncontra salvajes antes de la\pTorre. Acompáñalo ganando tres\ncombates."), COMPOUND_STRING("Pipo te ha observado con\natención. Dice que ya tiene un\pplan."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {140, 140, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Pipo quiere ir preparado a la\nTorre. Entrégale tres\pSuperpociones."), COMPOUND_STRING("Pipo guarda las Superpociones en\nsu mochila nueva."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {140, 139, RF_STORY_CHOICE, 0, 0x00000000, COMPOUND_STRING("Vega puede crear un reto para\nnovatos con su propia planta, o\pmantener la Torre igual y\nentrenar a los novatos fuera."), COMPOUND_STRING("Vega abre una planta para\nnovatos. Pipo será el primero en\psubir."), NULL, 0, NULL, RF_STORY_CHOICE_TORRE_CON_NOVATOS, COMPOUND_STRING("Vega pregunta: ¿creamos una\nplanta para novatos?"), NULL, COMPOUND_STRING("Vega decide entrenar a los\nnovatos en la playa. Cuando\pestén listos, subirán a la Torre\ncomo todos.")},
    {139, 140, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Pipo espera fuera de la Torre.\nVe a contarle lo que ha decidido\pVega."), COMPOUND_STRING("Pipo respira hondo y entra en la\nTorre."), NULL, 0, NULL, RF_STORY_CHOICE_TORRE_CON_NOVATOS, NULL, NULL, COMPOUND_STRING("Pipo sonríe aliviado. Entrenará\nen la playa hasta sentirse\plisto.")},
    {140, 139, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Pipo ha completado su primer\nreto. Te pide que se lo cuentes\pa Vega."), COMPOUND_STRING("Vega apunta el nombre de Pipo en\nla pizarra de la entrada. Es el\pprimer novato del año."), NULL, 0, NULL, RF_STORY_CHOICE_TORRE_CON_NOVATOS, NULL, NULL, COMPOUND_STRING("Vega apunta el nombre de Pipo en\nla lista de la playa. Pronto\pestará en la pizarra de la\nTorre.")},
    {142, 142, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Tina se preocupa por su hermano\nRoque, que escala el Cañón\pSevault y siempre vuelve tarde."), COMPOUND_STRING("Tina quiere que alguien hable\ncon él. A ella no la escucha."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {142, 141, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Roque escala el cañón casi cada\ndía. Tina quiere que vuelva\pantes del anochecer."), COMPOUND_STRING("Roque dice que no se arriesga.\nSolo pierde la noción del\ptiempo."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {141, 141, RF_STORY_BATTLE, TRAINER_RF_STORY_27, 0x00000000, COMPOUND_STRING("Roque solo escucha a quien sabe\nmoverse en terreno difícil. Te\preta a un combate."), COMPOUND_STRING("Roque asiente. Está dispuesto a\nescucharte."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {141, 141, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Roque conoce las rocas pero no\ntanto a los Pokémon que viven\pentre ellas. Registra dos\ncapturas de tipo Roca."), COMPOUND_STRING("Roque apunta las especies.\nAlgunas le explican ruidos que\poía al escalar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {141, 142, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Roque propone llevar siempre una\nCuerda Huida. Tina se la dará\pantes de cada salida."), COMPOUND_STRING("Tina guarda la Cuerda Huida en\nla mochila de su hermano."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {142, 141, RF_STORY_RACE, 0, 0x00000000, COMPOUND_STRING("Tina quiere saber cuánto tarda\nRoque en volver desde la entrada\pdel cañón. Haz el recorrido\ninverso en menos de un minuto."), COMPOUND_STRING("Roque mira el reloj. Si sale a\nla hora, llegará a cenar."), NULL, 0, &sRace_349, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {141, 142, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Roque promete volver antes del\nanochecer. Lleva su promesa a\pTina."), COMPOUND_STRING("Tina sonríe. Esta vez lo cree."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {142, 141, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Roque ha vuelto a tiempo tres\ndías seguidos. Tina te da su\pcena favorita para él."), COMPOUND_STRING("Roque se come la cena en la\nentrada del cañón, mirando el\patardecer. Esta vez lo ve\nentero."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {143, 143, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Lin ayuda a quienes llegan a\nAzafrán sin conocer a nadie. Ha\pvisto a un chico perdido en la\nRuta 5."), COMPOUND_STRING("Lin te pide que hables con él. A\nveces una cara amable basta para\pempezar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {143, 144, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Omar acaba de llegar a Kanto.\nEstá solo en la Ruta 5 con su\pPokémon."), COMPOUND_STRING("Omar cuenta que viene de lejos y\nno sabe por dónde empezar."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {144, 144, RF_STORY_FIELD, 0, 0x00000000, COMPOUND_STRING("Omar no conoce los Pokémon de\nKanto. Enséñale capturando dos\pen la Ruta 5."), COMPOUND_STRING("Omar observa a tus Pokémon con\ncuriosidad. Algunos se parecen a\plos de su tierra."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {144, 143, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Omar tiene muchas preguntas\nsobre la ciudad. Lleva su lista\pa Lin."), COMPOUND_STRING("Lin responde a cada pregunta en\nun mapa dibujado a mano."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {143, 144, RF_STORY_DELIVERY, 0, 0x00000000, COMPOUND_STRING("Lin sugiere que Omar empiece con\nun botiquín. Entrégale tres\pPociones."), COMPOUND_STRING("Omar guarda las Pociones con\ncuidado. Es lo primero que tiene\pde Kanto."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {144, 144, RF_STORY_PUZZLE, 0, 0x00000000, COMPOUND_STRING("Omar quiere comprobar que ha\nentendido el mapa de Lin."), COMPOUND_STRING("Omar sonríe. Ya sabe ir del\nCentro Pokémon al Gimnasio sin\pperderse."), sPuzzle_357, 3, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
    {144, 143, RF_STORY_TALK, 0, 0x00000000, COMPOUND_STRING("Omar ha encontrado un sitio\ndonde quedarse. Te pide que\pagradezcas a Lin."), COMPOUND_STRING("Lin guarda la nota de Omar junto\na otras muchas. Cada una es\palguien que ya no está perdido."), NULL, 0, NULL, RF_STORY_NO_CHOICE, NULL, NULL, NULL},
};
